INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score rates kids'' food and recipes out of {#} for your child''s age, from sugar, salt, saturated fat, fibre, protein and the ingredient list. Independent: no brand pays to be here.', 'hi', 'Poshan Score बच्चों के खाने और रेसिपी को आपके बच्चे की उम्र के लिए {#} में से स्कोर देता है, चीनी, नमक, सैचुरेटेड फैट, फाइबर, प्रोटीन और सामग्री की सूची के आधार पर। स्वतंत्र: कोई ब्रांड यहाँ आने के लिए भुगतान नहीं करता।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score rates kids'' food and recipes out of {#} for your child''s age, from sugar, salt, saturated fat, fibre, protein and the ingredient list. Independent: no brand pays to be here.', 'bn', 'Poshan Score বাচ্চাদের খাবার ও রেসিপিকে আপনার সন্তানের বয়সের জন্য {#}-এর মধ্যে স্কোর দেয়, চিনি, নুন, স্যাচুরেটেড ফ্যাট, ফাইবার, প্রোটিন ও উপকরণের তালিকার ভিত্তিতে। স্বাধীন: কোনো ব্র্যান্ড এখানে থাকার জন্য টাকা দেয় না।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score rates kids'' food and recipes out of {#} for your child''s age, from sugar, salt, saturated fat, fibre, protein and the ingredient list. Independent: no brand pays to be here.', 'gu', 'Poshan Score બાળકોના ખોરાક અને રેસીપીને તમારા બાળકની ઉંમર માટે {#} માંથી સ્કોર આપે છે, ખાંડ, મીઠું, સેચ્યુરેટેડ ફેટ, ફાઇબર, પ્રોટીન અને સામગ્રીની યાદીના આધારે. સ્વતંત્ર: કોઈ બ્રાન્ડ અહીં આવવા ચૂકવણી કરતી નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
