INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every pack says <em_a>healthy.</em_a><br_b/>Every recipe says <em_c>wholesome.</em_c><br_d/><span_e>We read what is really inside.</span_e>', 'hi', 'हर पैक कहता है <em_a>सेहतमंद।</em_a><br_b/>हर रेसिपी कहती है <em_c>पौष्टिक।</em_c><br_d/><span_e>हम देखते हैं असल में अंदर क्या है।</span_e>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every pack says <em_a>healthy.</em_a><br_b/>Every recipe says <em_c>wholesome.</em_c><br_d/><span_e>We read what is really inside.</span_e>', 'bn', 'প্রতিটি প্যাক বলে <em_a>স্বাস্থ্যকর।</em_a><br_b/>প্রতিটি রেসিপি বলে <em_c>পুষ্টিকর।</em_c><br_d/><span_e>আমরা দেখি আসলে ভেতরে কী আছে।</span_e>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every pack says <em_a>healthy.</em_a><br_b/>Every recipe says <em_c>wholesome.</em_c><br_d/><span_e>We read what is really inside.</span_e>', 'gu', 'દરેક પેક કહે છે <em_a>હેલ્ધી.</em_a><br_b/>દરેક રેસીપી કહે છે <em_c>પૌષ્ટિક.</em_c><br_d/><span_e>અમે જોઈએ છીએ ખરેખર અંદર શું છે.</span_e>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scan a pack or paste any recipe link. See its <b_a>real score for your child''s age</b_a>, and how much of what it brags about is actually inside.', 'hi', 'कोई पैक स्कैन करें या कोई भी रेसिपी लिंक चिपकाएँ। देखें <b_a>आपके बच्चे की उम्र के लिए असली स्कोर</b_a>, और वह जिस चीज़ का दावा करता है वह असल में कितनी है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scan a pack or paste any recipe link. See its <b_a>real score for your child''s age</b_a>, and how much of what it brags about is actually inside.', 'bn', 'একটি প্যাক স্ক্যান করুন বা যেকোনো রেসিপি লিঙ্ক পেস্ট করুন। দেখুন <b_a>আপনার সন্তানের বয়সের জন্য আসল স্কোর</b_a>, আর সে যা নিয়ে গর্ব করে তা আসলে কতটা আছে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scan a pack or paste any recipe link. See its <b_a>real score for your child''s age</b_a>, and how much of what it brags about is actually inside.', 'gu', 'કોઈ પેક સ્કેન કરો અથવા કોઈ પણ રેસીપી લિંક પેસ્ટ કરો. જુઓ <b_a>તમારા બાળકની ઉંમર માટે સાચો સ્કોર</b_a>, અને તે જે દાવો કરે છે તે ખરેખર કેટલું છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Type a <span_a>food</span_a> · a <span_b>brand</span_b> · or a <span_c>recipe link</span_c>', 'hi', 'लिखें <span_a>खाना</span_a> · <span_b>ब्रांड</span_b> · या <span_c>रेसिपी लिंक</span_c>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
