INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('From various cooks and cookbooks, each credited to the person who wrote it. Scored for the age you pick. <b_a>Tap the heart on any recipe to save it.</b_a>', 'hi', 'अलग-अलग रसोइयों और कुकबुक से, हर एक उसे लिखने वाले के नाम के साथ। आपकी चुनी उम्र के लिए स्कोर। <b_a>किसी भी रेसिपी पर दिल दबाकर उसे सेव करें।</b_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('From various cooks and cookbooks, each credited to the person who wrote it. Scored for the age you pick. <b_a>Tap the heart on any recipe to save it.</b_a>', 'bn', 'বিভিন্ন রাঁধুনি ও কুকবুক থেকে, প্রতিটি যিনি লিখেছেন তাঁর নামসহ। আপনার বেছে নেওয়া বয়সের জন্য স্কোর। <b_a>যেকোনো রেসিপিতে হার্ট চেপে সেটি সেভ করুন।</b_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('From various cooks and cookbooks, each credited to the person who wrote it. Scored for the age you pick. <b_a>Tap the heart on any recipe to save it.</b_a>', 'gu', 'જુદા જુદા રસોઇયાઓ અને કુકબુકમાંથી, દરેક તે લખનારના નામ સાથે. તમે પસંદ કરેલી ઉંમર માટે સ્કોર. <b_a>કોઈ પણ રેસીપી પર હાર્ટ દબાવીને તેને સેવ કરો.</b_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Hundreds of</b_a> recipes, by age, meal, season and food preference. Save the ones you like, then put them into a plan for the week: breakfast, lunch, a {#} PM snack and dinner, for every day.', 'hi', '<b_a>सैकड़ों</b_a> रेसिपी, उम्र, भोजन, मौसम और खाने की पसंद के हिसाब से। जो पसंद आएँ उन्हें सेव करें, फिर उन्हें हफ़्ते की योजना में रखें: नाश्ता, दोपहर का खाना, शाम {#} बजे का स्नैक और रात का खाना, हर दिन के लिए।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Hundreds of</b_a> recipes, by age, meal, season and food preference. Save the ones you like, then put them into a plan for the week: breakfast, lunch, a {#} PM snack and dinner, for every day.', 'bn', '<b_a>শত শত</b_a> রেসিপি, বয়স, বেলা, ঋতু ও খাবারের পছন্দ অনুযায়ী। যেগুলো ভালো লাগে সেভ করুন, তারপর সপ্তাহের পরিকল্পনায় রাখুন: জলখাবার, দুপুরের খাবার, বিকেল {#}টার স্ন্যাক ও রাতের খাবার, প্রতিদিনের জন্য।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Hundreds of</b_a> recipes, by age, meal, season and food preference. Save the ones you like, then put them into a plan for the week: breakfast, lunch, a {#} PM snack and dinner, for every day.', 'gu', '<b_a>સેંકડો</b_a> રેસીપી, ઉંમર, ભોજન, ઋતુ અને ખોરાકની પસંદગી મુજબ. જે ગમે તે સેવ કરો, પછી તેને અઠવાડિયાના આયોજનમાં મૂકો: નાસ્તો, બપોરનું ભોજન, સાંજે {#} વાગ્યાનો નાસ્તો અને રાતનું ભોજન, દરરોજ માટે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<a_a>See every recipe</a_a>, each with its own page and score, or <a_b>browse ideas by taste, meal and age</a_b>.', 'hi', '<a_a>हर रेसिपी देखें</a_a>, हर एक का अपना पेज और स्कोर है, या <a_b>स्वाद, भोजन और उम्र के अनुसार आइडिया देखें</a_b>।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<a_a>See every recipe</a_a>, each with its own page and score, or <a_b>browse ideas by taste, meal and age</a_b>.', 'bn', '<a_a>প্রতিটি রেসিপি দেখুন</a_a>, প্রতিটির নিজস্ব পেজ ও স্কোর আছে, বা <a_b>স্বাদ, বেলা ও বয়স অনুযায়ী আইডিয়া দেখুন</a_b>।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<a_a>See every recipe</a_a>, each with its own page and score, or <a_b>browse ideas by taste, meal and age</a_b>.', 'gu', '<a_a>દરેક રેસીપી જુઓ</a_a>, દરેકનું પોતાનું પેજ અને સ્કોર છે, અથવા <a_b>સ્વાદ, ભોજન અને ઉંમર મુજબ આઈડિયા જુઓ</a_b>.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scored against Indian government nutrition guidelines (ICMR-NIN, FSSAI). <a_a>See how we score</a_a>', 'hi', 'भारत सरकार के पोषण दिशानिर्देशों (ICMR-NIN, FSSAI) के विरुद्ध स्कोर किया गया। <a_a>देखें हम कैसे स्कोर करते हैं</a_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scored against Indian government nutrition guidelines (ICMR-NIN, FSSAI). <a_a>See how we score</a_a>', 'bn', 'ভারত সরকারের পুষ্টি নির্দেশিকা (ICMR-NIN, FSSAI) অনুযায়ী স্কোর করা। <a_a>দেখুন আমরা কীভাবে স্কোর করি</a_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scored against Indian government nutrition guidelines (ICMR-NIN, FSSAI). <a_a>See how we score</a_a>', 'gu', 'ભારત સરકારની પોષણ માર્ગદર્શિકા (ICMR-NIN, FSSAI) મુજબ સ્કોર કરેલ. <a_a>જુઓ અમે કેવી રીતે સ્કોર કરીએ છીએ</a_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The same rubric for every product on the shelf — theirs and ours. Ten yes-or-no checks, each worth {#} points, worked out for the age group (and, from {#} years, boy or girl, man or woman) and one realistic serving. Six are numbers off the label, measured against that group''s daily reference. Three are checks on the ingredient list. The tenth fails if the sugar, sodium or saturated-fat check fails. Full citations and thresholds on the <a_a>Age & Metrics</a_a> page.', 'hi', 'शेल्फ़ पर रखे हर प्रोडक्ट के लिए एक ही रूब्रिक: उनके भी और हमारे भी। दस हाँ-या-नहीं जाँच, हर एक के {#} अंक, उम्र के समूह (और {#} साल से, लड़का या लड़की, पुरुष या महिला) और एक यथार्थवादी सर्विंग के हिसाब से। छह लेबल की संख्याएँ हैं, जिन्हें उस समूह के दैनिक संदर्भ से मापा जाता है। तीन सामग्री की सूची की जाँच हैं। दसवीं तब फेल होती है जब चीनी, सोडियम या सैचुरेटेड फैट की जाँच फेल हो। पूरे संदर्भ और सीमाएँ <a_a>उम्र और मापदंड</a_a> पेज पर हैं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The same rubric for every product on the shelf — theirs and ours. Ten yes-or-no checks, each worth {#} points, worked out for the age group (and, from {#} years, boy or girl, man or woman) and one realistic serving. Six are numbers off the label, measured against that group''s daily reference. Three are checks on the ingredient list. The tenth fails if the sugar, sodium or saturated-fat check fails. Full citations and thresholds on the <a_a>Age & Metrics</a_a> page.', 'bn', 'তাকে রাখা প্রতিটি প্রোডাক্টের জন্য একই রুব্রিক: তাদেরও, আমাদেরও। দশটি হ্যাঁ-না পরীক্ষা, প্রতিটির {#} নম্বর, বয়সের গ্রুপ (এবং {#} বছর থেকে ছেলে বা মেয়ে, পুরুষ বা মহিলা) ও একটি বাস্তবসম্মত সার্ভিং অনুযায়ী। ছয়টি লেবেলের সংখ্যা, ওই গ্রুপের দৈনিক রেফারেন্সের সঙ্গে মাপা। তিনটি উপকরণের তালিকার পরীক্ষা। দশমটি ফেল করে যদি চিনি, সোডিয়াম বা স্যাচুরেটেড ফ্যাটের পরীক্ষা ফেল করে। পূর্ণ তথ্যসূত্র ও সীমা <a_a>বয়স ও মাপকাঠি</a_a> পেজে আছে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The same rubric for every product on the shelf — theirs and ours. Ten yes-or-no checks, each worth {#} points, worked out for the age group (and, from {#} years, boy or girl, man or woman) and one realistic serving. Six are numbers off the label, measured against that group''s daily reference. Three are checks on the ingredient list. The tenth fails if the sugar, sodium or saturated-fat check fails. Full citations and thresholds on the <a_a>Age & Metrics</a_a> page.', 'gu', 'શેલ્ફ પરના દરેક પ્રોડક્ટ માટે એક જ રૂબ્રિક: તેમના પણ અને અમારા પણ. દસ હા-કે-ના તપાસ, દરેકના {#} ગુણ, ઉંમર જૂથ (અને {#} વર્ષથી, છોકરો કે છોકરી, પુરુષ કે સ્ત્રી) અને એક વાસ્તવિક સર્વિંગ મુજબ. છ લેબલની સંખ્યાઓ છે, તે જૂથના દૈનિક સંદર્ભ સામે માપેલી. ત્રણ સામગ્રીની યાદીની તપાસ છે. દસમી ત્યારે નાપાસ થાય છે જ્યારે ખાંડ, સોડિયમ કે સેચ્યુરેટેડ ફેટની તપાસ નાપાસ થાય. પૂરા સંદર્ભો અને મર્યાદાઓ <a_a>ઉંમર અને માપદંડ</a_a> પેજ પર છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s free-sugar limit for that age group ({#}% for snacks and sweets). The limit is {#}% of energy, from WHO, on ICMR-NIN energy.', 'hi', 'हाँ अगर एक सर्विंग उस उम्र समूह की दिन की फ्री-शुगर सीमा के {#}% से कम रहे (स्नैक्स और मिठाइयों के लिए {#}%)। सीमा ऊर्जा का {#}% है, WHO से, ICMR-NIN की ऊर्जा पर।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s free-sugar limit for that age group ({#}% for snacks and sweets). The limit is {#}% of energy, from WHO, on ICMR-NIN energy.', 'bn', 'হ্যাঁ, যদি এক সার্ভিং ওই বয়সের গ্রুপের দিনের ফ্রি-সুগার সীমার {#}%-এর কম থাকে (স্ন্যাকস ও মিষ্টির জন্য {#}%)। সীমা শক্তির {#}%, WHO থেকে, ICMR-NIN-এর শক্তির ওপর।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s free-sugar limit for that age group ({#}% for snacks and sweets). The limit is {#}% of energy, from WHO, on ICMR-NIN energy.', 'gu', 'હા, જો એક સર્વિંગ તે ઉંમર જૂથની દિવસની ફ્રી-શુગર મર્યાદાના {#}% થી ઓછી રહે (સ્નૅક્સ અને મીઠાઈ માટે {#}%). મર્યાદા ઊર્જાના {#}% છે, WHO પરથી, ICMR-NIN ની ઊર્જા પર.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s sodium ({#}% for snacks and sweets). ICMR-NIN''s adult limit is {#} mg; for children we scale it down by energy.', 'hi', 'हाँ अगर एक सर्विंग दिन के सोडियम के {#}% से कम रहे (स्नैक्स और मिठाइयों के लिए {#}%)। ICMR-NIN की वयस्क सीमा {#} मि.ग्रा. है; बच्चों के लिए हम इसे ऊर्जा के हिसाब से घटाते हैं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s sodium ({#}% for snacks and sweets). ICMR-NIN''s adult limit is {#} mg; for children we scale it down by energy.', 'bn', 'হ্যাঁ, যদি এক সার্ভিং দিনের সোডিয়ামের {#}%-এর কম থাকে (স্ন্যাকস ও মিষ্টির জন্য {#}%)। ICMR-NIN-এর প্রাপ্তবয়স্ক সীমা {#} মিগ্রা; শিশুদের জন্য আমরা শক্তি অনুযায়ী তা কমাই।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s sodium ({#}% for snacks and sweets). ICMR-NIN''s adult limit is {#} mg; for children we scale it down by energy.', 'gu', 'હા, જો એક સર્વિંગ દિવસના સોડિયમના {#}% થી ઓછી રહે (સ્નૅક્સ અને મીઠાઈ માટે {#}%). ICMR-NIN ની પુખ્ત મર્યાદા {#} મિ.ગ્રા. છે; બાળકો માટે અમે તેને ઊર્જા મુજબ ઘટાડીએ છીએ.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s limit ({#}% for snacks and sweets). The limit is WHO''s under {#}% of energy.', 'hi', 'हाँ अगर एक सर्विंग दिन की सीमा के {#}% से कम रहे (स्नैक्स और मिठाइयों के लिए {#}%)। सीमा WHO की ऊर्जा के {#}% से कम है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s limit ({#}% for snacks and sweets). The limit is WHO''s under {#}% of energy.', 'bn', 'হ্যাঁ, যদি এক সার্ভিং দিনের সীমার {#}%-এর কম থাকে (স্ন্যাকস ও মিষ্টির জন্য {#}%)। সীমা WHO-র শক্তির {#}%-এর কম।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving stays under {#}% of the day''s limit ({#}% for snacks and sweets). The limit is WHO''s under {#}% of energy.', 'gu', 'હા, જો એક સર્વિંગ દિવસની મર્યાદાના {#}% થી ઓછી રહે (સ્નૅક્સ અને મીઠાઈ માટે {#}%). મર્યાદા WHO ની ઊર્જાના {#}% થી ઓછી છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if no hydrogenated oil, vanaspati or margarine is listed. FSSAI caps industrial trans fat at {#}% of oils and fats, the same at every age.', 'hi', 'हाँ अगर कोई हाइड्रोजनीकृत तेल, वनस्पति या मार्जरीन सूची में न हो। FSSAI औद्योगिक ट्रांस फैट को तेलों और वसा के {#}% पर सीमित करता है, हर उम्र के लिए समान।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if no hydrogenated oil, vanaspati or margarine is listed. FSSAI caps industrial trans fat at {#}% of oils and fats, the same at every age.', 'bn', 'হ্যাঁ, যদি কোনো হাইড্রোজেনেটেড তেল, বনস্পতি বা মার্জারিন তালিকায় না থাকে। FSSAI শিল্পজাত ট্রান্স ফ্যাট তেল ও ফ্যাটের {#}%-এ সীমিত করে, সব বয়সে একই।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if no hydrogenated oil, vanaspati or margarine is listed. FSSAI caps industrial trans fat at {#}% of oils and fats, the same at every age.', 'gu', 'હા, જો કોઈ હાઇડ્રોજનેટેડ તેલ, વનસ્પતિ કે માર્જરિન યાદીમાં ન હોય. FSSAI ઔદ્યોગિક ટ્રાન્સ ફેટને તેલ અને ચરબીના {#}% સુધી મર્યાદિત કરે છે, દરેક ઉંમરે સમાન.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving gives at least {#}% of the day''s protein for that age group, sex and kind of work, from the ICMR-NIN {#} RDAs.', 'hi', 'हाँ अगर एक सर्विंग उस उम्र समूह, लिंग और काम के प्रकार के दिन के प्रोटीन का कम से कम {#}% दे, ICMR-NIN {#} के RDA से।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving gives at least {#}% of the day''s protein for that age group, sex and kind of work, from the ICMR-NIN {#} RDAs.', 'bn', 'হ্যাঁ, যদি এক সার্ভিং ওই বয়সের গ্রুপ, লিঙ্গ ও কাজের ধরনের দিনের প্রোটিনের অন্তত {#}% দেয়, ICMR-NIN {#}-এর RDA থেকে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if one serving gives at least {#}% of the day''s protein for that age group, sex and kind of work, from the ICMR-NIN {#} RDAs.', 'gu', 'હા, જો એક સર્વિંગ તે ઉંમર જૂથ, જાતિ અને કામના પ્રકારના દિવસના પ્રોટીનના ઓછામાં ઓછા {#}% આપે, ICMR-NIN {#} ના RDA પરથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if no Class II preservative is named in the ingredients: the ones parents recognise least, checked most.', 'hi', 'हाँ अगर सामग्री में कोई क्लास II प्रिज़र्वेटिव न हो: जिन्हें अभिभावक सबसे कम पहचानते हैं, और जिन्हें सबसे ज़्यादा जाँचा जाता है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if no Class II preservative is named in the ingredients: the ones parents recognise least, checked most.', 'bn', 'হ্যাঁ, যদি উপকরণে কোনো ক্লাস II প্রিজারভেটিভ না থাকে: যেগুলো অভিভাবকরা সবচেয়ে কম চেনেন, আর সবচেয়ে বেশি দেখা হয়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes if no Class II preservative is named in the ingredients: the ones parents recognise least, checked most.', 'gu', 'હા, જો સામગ્રીમાં કોઈ ક્લાસ II પ્રિઝર્વેટિવ ન હોય: જેને વાલીઓ સૌથી ઓછું ઓળખે છે, અને સૌથી વધુ તપાસાય છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes only if the sugar, sodium and saturated-fat checks all pass. Echoes FSSAI''s pending front-of-pack warning for foods high in fat, sugar or salt.', 'hi', 'हाँ सिर्फ़ तब जब चीनी, सोडियम और सैचुरेटेड फैट की तीनों जाँच पास हों। ज़्यादा वसा, चीनी या नमक वाले खाने के लिए FSSAI की लंबित फ्रंट-ऑफ-पैक चेतावनी से मेल खाता है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes only if the sugar, sodium and saturated-fat checks all pass. Echoes FSSAI''s pending front-of-pack warning for foods high in fat, sugar or salt.', 'bn', 'হ্যাঁ শুধুমাত্র যদি চিনি, সোডিয়াম ও স্যাচুরেটেড ফ্যাটের তিনটি পরীক্ষাই পাস করে। বেশি ফ্যাট, চিনি বা নুনের খাবারের জন্য FSSAI-এর বিচারাধীন প্যাকের সামনের সতর্কতার সঙ্গে মেলে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Yes only if the sugar, sodium and saturated-fat checks all pass. Echoes FSSAI''s pending front-of-pack warning for foods high in fat, sugar or salt.', 'gu', 'હા, ફક્ત ત્યારે જ જ્યારે ખાંડ, સોડિયમ અને સેચ્યુરેટેડ ફેટની ત્રણેય તપાસ પાસ થાય. વધુ ચરબી, ખાંડ કે મીઠાવાળા ખોરાક માટે FSSAI ની બાકી ફ્રન્ટ-ઓફ-પેક ચેતવણી સાથે મળતું આવે છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Kids'' foods from the shelf, each scored from its nutrition label, with an age guide from {#} months to adults.', 'hi', 'शेल्फ़ पर बच्चों के खाने, हर एक अपने पोषण लेबल से स्कोर किया गया, {#} महीने से वयस्कों तक के उम्र गाइड के साथ।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Kids'' foods from the shelf, each scored from its nutrition label, with an age guide from {#} months to adults.', 'bn', 'তাকে রাখা বাচ্চাদের খাবার, প্রতিটি তার পুষ্টি লেবেল থেকে স্কোর করা, {#} মাস থেকে প্রাপ্তবয়স্ক পর্যন্ত বয়সের নির্দেশিকাসহ।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Kids'' foods from the shelf, each scored from its nutrition label, with an age guide from {#} months to adults.', 'gu', 'શેલ્ફ પરના બાળકોના ખોરાક, દરેક તેના પોષણ લેબલ પરથી સ્કોર કરેલ, {#} મહિનાથી પુખ્ત સુધીની ઉંમર માર્ગદર્શિકા સાથે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Recipes for your child''s age, meal and season, each with its own Poshan Score, plus ready-made packs and the ingredients to buy.', 'hi', 'आपके बच्चे की उम्र, भोजन और मौसम के लिए रेसिपी, हर एक का अपना Poshan Score, साथ में तैयार पैक और खरीदने की सामग्री।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Recipes for your child''s age, meal and season, each with its own Poshan Score, plus ready-made packs and the ingredients to buy.', 'bn', 'আপনার সন্তানের বয়স, বেলা ও ঋতুর জন্য রেসিপি, প্রতিটির নিজস্ব Poshan Score, সঙ্গে তৈরি প্যাক ও কেনার উপকরণ।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Recipes for your child''s age, meal and season, each with its own Poshan Score, plus ready-made packs and the ingredients to buy.', 'gu', 'તમારા બાળકની ઉંમર, ભોજન અને ઋતુ માટે રેસીપી, દરેકનો પોતાનો Poshan Score, સાથે તૈયાર પેક અને ખરીદવાની સામગ્રી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification · No brand pays to be here', 'hi', '<b_a>ICMR-NIN {#}</b_a> और <b_b>FSSAI</b_b> के मानक पर · Poshan Score एक स्वतंत्र रेटिंग है, कोई प्रमाणन नहीं · कोई ब्रांड यहाँ आने के लिए भुगतान नहीं करता', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification · No brand pays to be here', 'bn', '<b_a>ICMR-NIN {#}</b_a> ও <b_b>FSSAI</b_b> মানদণ্ডে · Poshan Score একটি স্বাধীন রেটিং, কোনো সার্টিফিকেশন নয় · কোনো ব্র্যান্ড এখানে থাকার জন্য টাকা দেয় না', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification · No brand pays to be here', 'gu', '<b_a>ICMR-NIN {#}</b_a> અને <b_b>FSSAI</b_b> ના ધોરણ પર · Poshan Score એક સ્વતંત્ર રેટિંગ છે, પ્રમાણપત્ર નથી · કોઈ બ્રાન્ડ અહીં આવવા ચૂકવણી કરતી નથી', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('How the Poshan Score works: ten yes-or-no checks, worked out for every ICMR-NIN age group, from {#} months to adults, from ICMR-NIN, WHO and FSSAI references. Every threshold and source is listed.', 'hi', 'Poshan Score कैसे काम करता है: दस हाँ-या-नहीं जाँच, ICMR-NIN के हर उम्र समूह के लिए, {#} महीने से वयस्कों तक, ICMR-NIN, WHO और FSSAI के संदर्भों से। हर सीमा और स्रोत सूचीबद्ध है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('How the Poshan Score works: ten yes-or-no checks, worked out for every ICMR-NIN age group, from {#} months to adults, from ICMR-NIN, WHO and FSSAI references. Every threshold and source is listed.', 'bn', 'Poshan Score কীভাবে কাজ করে: দশটি হ্যাঁ-না পরীক্ষা, ICMR-NIN-এর প্রতিটি বয়সের গ্রুপের জন্য, {#} মাস থেকে প্রাপ্তবয়স্ক পর্যন্ত, ICMR-NIN, WHO ও FSSAI-এর রেফারেন্স থেকে। প্রতিটি সীমা ও উৎস তালিকাভুক্ত।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('How the Poshan Score works: ten yes-or-no checks, worked out for every ICMR-NIN age group, from {#} months to adults, from ICMR-NIN, WHO and FSSAI references. Every threshold and source is listed.', 'gu', 'Poshan Score કેવી રીતે કામ કરે છે: દસ હા-કે-ના તપાસ, ICMR-NIN ના દરેક ઉંમર જૂથ માટે, {#} મહિનાથી પુખ્ત સુધી, ICMR-NIN, WHO અને FSSAI ના સંદર્ભો પરથી. દરેક મર્યાદા અને સ્રોત યાદીબદ્ધ છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product and every recipe gets <b_a>one score from {#} to {#}</b_a>. Each of the ten checks is a plain <b_b>yes ({#}) or no ({#})</b_b>, and the score is the number passed times {#}, so a product that passes everything scores exactly {#} and one that passes nothing scores {#}. Six of them are numbers off the label, measured as a share of the daily reference for the age group (and, from {#} years, the sex and kind of work): <b_c>added sugar, sodium, saturated fat, trans fat, fibre and protein</b_c>. Fibre and protein are <b_d>credit</b_d> metrics (more is better); the others are <b_e>risk</b_e> metrics (less is better). Three more are checks that do not change with age: <b_f>preservatives, artificial additives and base-ingredient integrity</b_f>. The tenth is <b_g>HFSS</b_g>, which fails if the sugar, sodium or saturated-fat check fails. A product that fails any one risk check is held at <b_h>OK</b_h>: the score still shows the real count, with a "capped" badge. Packs and recipes are scored the same way, per realistic serving, so they can be compared. The same method is used on the Products and Meal Ideas pages. Every number below is cited, and the sources are listed at the bottom of this page.', 'hi', 'हर प्रोडक्ट और हर रेसिपी को <b_a>{#} से {#} तक एक स्कोर</b_a> मिलता है। दसों जाँच में से हर एक सीधी <b_b>हाँ ({#}) या नहीं ({#})</b_b> है, और स्कोर पास हुई जाँच की संख्या गुणा {#} है, इसलिए जो सब कुछ पास करे उसे ठीक {#} और जो कुछ भी पास न करे उसे {#} मिलता है। इनमें से छह लेबल की संख्याएँ हैं, जिन्हें उम्र समूह (और {#} साल से, लिंग और काम के प्रकार) के दैनिक संदर्भ के हिस्से के रूप में मापा जाता है: <b_c>एडेड शुगर, सोडियम, सैचुरेटेड फैट, ट्रांस फैट, फाइबर और प्रोटीन</b_c>। फाइबर और प्रोटीन <b_d>क्रेडिट</b_d> मापदंड हैं (ज़्यादा बेहतर); बाकी <b_e>जोखिम</b_e> मापदंड हैं (कम बेहतर)। तीन और जाँच उम्र के साथ नहीं बदलतीं: <b_f>प्रिज़र्वेटिव, कृत्रिम एडिटिव और मुख्य सामग्री की गुणवत्ता</b_f>। दसवीं <b_g>HFSS</b_g> है, जो तब फेल होती है जब चीनी, सोडियम या सैचुरेटेड फैट की जाँच फेल हो। जो प्रोडक्ट किसी भी एक जोखिम जाँच में फेल होता है उसे <b_h>ठीक</b_h> पर रोक दिया जाता है: स्कोर में असली गिनती दिखती है, "रोका गया" बैज के साथ। पैक और रेसिपी को एक ही तरह से, प्रति यथार्थवादी सर्विंग, स्कोर किया जाता है, ताकि उनकी तुलना हो सके। यही तरीका प्रोडक्ट और मील आइडिया पेजों पर इस्तेमाल होता है। नीचे की हर संख्या का स्रोत दिया गया है, और स्रोत इस पेज के अंत में सूचीबद्ध हैं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product and every recipe gets <b_a>one score from {#} to {#}</b_a>. Each of the ten checks is a plain <b_b>yes ({#}) or no ({#})</b_b>, and the score is the number passed times {#}, so a product that passes everything scores exactly {#} and one that passes nothing scores {#}. Six of them are numbers off the label, measured as a share of the daily reference for the age group (and, from {#} years, the sex and kind of work): <b_c>added sugar, sodium, saturated fat, trans fat, fibre and protein</b_c>. Fibre and protein are <b_d>credit</b_d> metrics (more is better); the others are <b_e>risk</b_e> metrics (less is better). Three more are checks that do not change with age: <b_f>preservatives, artificial additives and base-ingredient integrity</b_f>. The tenth is <b_g>HFSS</b_g>, which fails if the sugar, sodium or saturated-fat check fails. A product that fails any one risk check is held at <b_h>OK</b_h>: the score still shows the real count, with a "capped" badge. Packs and recipes are scored the same way, per realistic serving, so they can be compared. The same method is used on the Products and Meal Ideas pages. Every number below is cited, and the sources are listed at the bottom of this page.', 'bn', 'প্রতিটি প্রোডাক্ট ও প্রতিটি রেসিপি পায় <b_a>{#} থেকে {#} পর্যন্ত একটি স্কোর</b_a>। দশটি পরীক্ষার প্রতিটি সরল <b_b>হ্যাঁ ({#}) বা না ({#})</b_b>, আর স্কোর হল পাস করা পরীক্ষার সংখ্যা গুণ {#}, তাই যে সব পাস করে সে ঠিক {#} পায় আর যে কিছুই পাস করে না সে {#} পায়। এর ছয়টি লেবেলের সংখ্যা, বয়সের গ্রুপের (এবং {#} বছর থেকে, লিঙ্গ ও কাজের ধরনের) দৈনিক রেফারেন্সের অংশ হিসেবে মাপা: <b_c>অ্যাডেড সুগার, সোডিয়াম, স্যাচুরেটেড ফ্যাট, ট্রান্স ফ্যাট, ফাইবার ও প্রোটিন</b_c>। ফাইবার ও প্রোটিন <b_d>ক্রেডিট</b_d> মাপকাঠি (বেশি ভালো); বাকিগুলো <b_e>ঝুঁকি</b_e> মাপকাঠি (কম ভালো)। আরও তিনটি পরীক্ষা বয়সের সঙ্গে বদলায় না: <b_f>প্রিজারভেটিভ, কৃত্রিম অ্যাডিটিভ ও মূল উপকরণের মান</b_f>। দশমটি <b_g>HFSS</b_g>, যা ফেল করে যদি চিনি, সোডিয়াম বা স্যাচুরেটেড ফ্যাটের পরীক্ষা ফেল করে। যে প্রোডাক্ট যেকোনো একটি ঝুঁকির পরীক্ষায় ফেল করে তাকে <b_h>মোটামুটি</b_h>-তে আটকে রাখা হয়: স্কোরে আসল গণনা দেখায়, "আটকানো" ব্যাজসহ। প্যাক ও রেসিপি একইভাবে, প্রতি বাস্তবসম্মত সার্ভিংয়ে স্কোর করা হয়, যাতে তুলনা করা যায়। একই পদ্ধতি প্রোডাক্ট ও মিল আইডিয়া পেজে ব্যবহার হয়। নিচের প্রতিটি সংখ্যার উৎস দেওয়া আছে, আর উৎসগুলো এই পেজের শেষে তালিকাভুক্ত।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product and every recipe gets <b_a>one score from {#} to {#}</b_a>. Each of the ten checks is a plain <b_b>yes ({#}) or no ({#})</b_b>, and the score is the number passed times {#}, so a product that passes everything scores exactly {#} and one that passes nothing scores {#}. Six of them are numbers off the label, measured as a share of the daily reference for the age group (and, from {#} years, the sex and kind of work): <b_c>added sugar, sodium, saturated fat, trans fat, fibre and protein</b_c>. Fibre and protein are <b_d>credit</b_d> metrics (more is better); the others are <b_e>risk</b_e> metrics (less is better). Three more are checks that do not change with age: <b_f>preservatives, artificial additives and base-ingredient integrity</b_f>. The tenth is <b_g>HFSS</b_g>, which fails if the sugar, sodium or saturated-fat check fails. A product that fails any one risk check is held at <b_h>OK</b_h>: the score still shows the real count, with a "capped" badge. Packs and recipes are scored the same way, per realistic serving, so they can be compared. The same method is used on the Products and Meal Ideas pages. Every number below is cited, and the sources are listed at the bottom of this page.', 'gu', 'દરેક પ્રોડક્ટ અને દરેક રેસીપીને <b_a>{#} થી {#} સુધીનો એક સ્કોર</b_a> મળે છે. દસેય તપાસમાંથી દરેક સીધી <b_b>હા ({#}) કે ના ({#})</b_b> છે, અને સ્કોર પાસ થયેલી તપાસની સંખ્યા ગુણ્યા {#} છે, તેથી જે બધું પાસ કરે તેને બરાબર {#} અને જે કંઈ પાસ ન કરે તેને {#} મળે છે. તેમાંથી છ લેબલની સંખ્યાઓ છે, ઉંમર જૂથ (અને {#} વર્ષથી, જાતિ અને કામના પ્રકાર) ના દૈનિક સંદર્ભના હિસ્સા તરીકે માપેલી: <b_c>એડેડ શુગર, સોડિયમ, સેચ્યુરેટેડ ફેટ, ટ્રાન્સ ફેટ, ફાઇબર અને પ્રોટીન</b_c>. ફાઇબર અને પ્રોટીન <b_d>ક્રેડિટ</b_d> માપદંડ છે (વધુ સારું); બાકીના <b_e>જોખમ</b_e> માપદંડ છે (ઓછું સારું). વધુ ત્રણ તપાસ ઉંમર સાથે બદલાતી નથી: <b_f>પ્રિઝર્વેટિવ, કૃત્રિમ એડિટિવ અને મુખ્ય સામગ્રીની ગુણવત્તા</b_f>. દસમી <b_g>HFSS</b_g> છે, જે ત્યારે નાપાસ થાય છે જ્યારે ખાંડ, સોડિયમ કે સેચ્યુરેટેડ ફેટની તપાસ નાપાસ થાય. જે પ્રોડક્ટ કોઈ પણ એક જોખમ તપાસમાં નાપાસ થાય તેને <b_h>ઠીક</b_h> પર રોકી રાખવામાં આવે છે: સ્કોર સાચી ગણતરી બતાવે છે, "રોકાયેલ" બેજ સાથે. પેક અને રેસીપી એક જ રીતે, પ્રતિ વાસ્તવિક સર્વિંગ, સ્કોર થાય છે, જેથી તેમની સરખામણી થઈ શકે. આ જ પદ્ધતિ પ્રોડક્ટ અને મીલ આઈડિયા પેજ પર વપરાય છે. નીચેની દરેક સંખ્યાનો સ્રોત આપેલ છે, અને સ્રોતો આ પેજના અંતે યાદીબદ્ધ છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The age groups are the ones the ICMR-NIN {#} table uses: {#}–{#}, {#}–{#} and {#}–{#} years; boys and girls at {#}–{#}, {#}–{#} and {#}–{#}; and adults, men and women at sedentary, moderate or heavy work. Under {#} months we use the {#}–{#} year reference. Tap a group to see its reference numbers. Pregnant and lactating women are not scored yet.', 'hi', 'उम्र के समूह वही हैं जो ICMR-NIN {#} की तालिका में हैं: {#}–{#}, {#}–{#} और {#}–{#} साल; लड़के और लड़कियाँ {#}–{#}, {#}–{#} और {#}–{#} पर; और वयस्क, पुरुष और महिलाएँ, बैठे रहने वाले, मध्यम या भारी काम पर। {#} महीने से कम के लिए हम {#}–{#} साल का संदर्भ इस्तेमाल करते हैं। किसी समूह पर टैप करें तो उसकी संदर्भ संख्याएँ दिखेंगी। गर्भवती और स्तनपान कराने वाली महिलाओं को अभी स्कोर नहीं किया जाता।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The age groups are the ones the ICMR-NIN {#} table uses: {#}–{#}, {#}–{#} and {#}–{#} years; boys and girls at {#}–{#}, {#}–{#} and {#}–{#}; and adults, men and women at sedentary, moderate or heavy work. Under {#} months we use the {#}–{#} year reference. Tap a group to see its reference numbers. Pregnant and lactating women are not scored yet.', 'bn', 'বয়সের গ্রুপগুলো ICMR-NIN {#} তালিকার মতোই: {#}–{#}, {#}–{#} ও {#}–{#} বছর; ছেলে ও মেয়ে {#}–{#}, {#}–{#} ও {#}–{#}; এবং প্রাপ্তবয়স্ক, পুরুষ ও মহিলা, বসে থাকার, মাঝারি বা ভারী কাজে। {#} মাসের কমের জন্য আমরা {#}–{#} বছরের রেফারেন্স ব্যবহার করি। কোনো গ্রুপে ট্যাপ করলে তার রেফারেন্স সংখ্যা দেখাবে। গর্ভবতী ও স্তন্যদানকারী মহিলাদের এখনও স্কোর করা হয় না।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The age groups are the ones the ICMR-NIN {#} table uses: {#}–{#}, {#}–{#} and {#}–{#} years; boys and girls at {#}–{#}, {#}–{#} and {#}–{#}; and adults, men and women at sedentary, moderate or heavy work. Under {#} months we use the {#}–{#} year reference. Tap a group to see its reference numbers. Pregnant and lactating women are not scored yet.', 'gu', 'ઉંમર જૂથો ICMR-NIN {#} ના કોષ્ટકમાં છે તે જ છે: {#}–{#}, {#}–{#} અને {#}–{#} વર્ષ; છોકરા અને છોકરીઓ {#}–{#}, {#}–{#} અને {#}–{#}; અને પુખ્ત, પુરુષ અને સ્ત્રીઓ, બેસી રહેવાના, મધ્યમ કે ભારે કામ પર. {#} મહિનાથી ઓછા માટે અમે {#}–{#} વર્ષનો સંદર્ભ વાપરીએ છીએ. કોઈ જૂથ પર ટૅપ કરો તો તેની સંદર્ભ સંખ્યાઓ દેખાશે. ગર્ભવતી અને સ્તનપાન કરાવતી સ્ત્રીઓને હજી સ્કોર થતો નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Under {#} months there is no published reference band, so the <b_a>{#}–{#} years</b_a> reference numbers are used. Only plain foods meant for babies are scored: a product with added sugar or salt is shown as “Not for under {#}”, not as a number.', 'hi', '{#} महीने से कम के लिए कोई प्रकाशित संदर्भ समूह नहीं है, इसलिए <b_a>{#}–{#} साल</b_a> की संदर्भ संख्याएँ इस्तेमाल होती हैं। सिर्फ़ शिशुओं के लिए बने सादे खाने स्कोर किए जाते हैं: चीनी या नमक मिला प्रोडक्ट “{#} से कम के लिए नहीं” दिखता है, संख्या के रूप में नहीं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Under {#} months there is no published reference band, so the <b_a>{#}–{#} years</b_a> reference numbers are used. Only plain foods meant for babies are scored: a product with added sugar or salt is shown as “Not for under {#}”, not as a number.', 'bn', '{#} মাসের কমের জন্য কোনো প্রকাশিত রেফারেন্স গ্রুপ নেই, তাই <b_a>{#}–{#} বছর</b_a>-এর রেফারেন্স সংখ্যা ব্যবহার হয়। শুধু শিশুদের জন্য তৈরি সাদাসিধে খাবার স্কোর করা হয়: চিনি বা নুন মেশানো প্রোডাক্ট “{#}-এর কমের জন্য নয়” দেখায়, সংখ্যা হিসেবে নয়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Under {#} months there is no published reference band, so the <b_a>{#}–{#} years</b_a> reference numbers are used. Only plain foods meant for babies are scored: a product with added sugar or salt is shown as “Not for under {#}”, not as a number.', 'gu', '{#} મહિનાથી ઓછા માટે કોઈ પ્રકાશિત સંદર્ભ જૂથ નથી, તેથી <b_a>{#}–{#} વર્ષ</b_a> ની સંદર્ભ સંખ્યાઓ વપરાય છે. ફક્ત શિશુઓ માટેના સાદા ખોરાક સ્કોર થાય છે: ખાંડ કે મીઠું ઉમેરેલ પ્રોડક્ટ “{#} થી ઓછા માટે નહીં” દેખાય છે, સંખ્યા તરીકે નહીં.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
