INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Energy, protein and fibre are the ICMR-NIN {#} figures for each group (energy is NIN''s estimated requirement). Added sugar is {#}% of energy (upper {#}%) and saturated fat {#}% of energy (WHO). Sodium is the ICMR-NIN {#} adult limit of {#} mg, scaled down by energy for younger children. The row without a sex is the average of the two.', 'hi', 'ऊर्जा, प्रोटीन और फाइबर हर समूह के लिए ICMR-NIN {#} के आँकड़े हैं (ऊर्जा NIN की अनुमानित आवश्यकता है)। एडेड शुगर ऊर्जा का {#}% (ऊपरी {#}%) और सैचुरेटेड फैट ऊर्जा का {#}% (WHO) है। सोडियम ICMR-NIN {#} की वयस्क सीमा {#} मि.ग्रा. है, छोटे बच्चों के लिए ऊर्जा के हिसाब से घटाई गई। जिस पंक्ति में लिंग नहीं है वह दोनों का औसत है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Energy, protein and fibre are the ICMR-NIN {#} figures for each group (energy is NIN''s estimated requirement). Added sugar is {#}% of energy (upper {#}%) and saturated fat {#}% of energy (WHO). Sodium is the ICMR-NIN {#} adult limit of {#} mg, scaled down by energy for younger children. The row without a sex is the average of the two.', 'bn', 'শক্তি, প্রোটিন ও ফাইবার প্রতিটি গ্রুপের জন্য ICMR-NIN {#}-এর সংখ্যা (শক্তি NIN-এর আনুমানিক প্রয়োজন)। অ্যাডেড সুগার শক্তির {#}% (ঊর্ধ্ব {#}%) ও স্যাচুরেটেড ফ্যাট শক্তির {#}% (WHO)। সোডিয়াম ICMR-NIN {#}-এর প্রাপ্তবয়স্ক সীমা {#} মিগ্রা, ছোট শিশুদের জন্য শক্তি অনুযায়ী কমানো। যে সারিতে লিঙ্গ নেই তা দুটির গড়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Energy, protein and fibre are the ICMR-NIN {#} figures for each group (energy is NIN''s estimated requirement). Added sugar is {#}% of energy (upper {#}%) and saturated fat {#}% of energy (WHO). Sodium is the ICMR-NIN {#} adult limit of {#} mg, scaled down by energy for younger children. The row without a sex is the average of the two.', 'gu', 'ઊર્જા, પ્રોટીન અને ફાઇબર દરેક જૂથ માટે ICMR-NIN {#} ના આંકડા છે (ઊર્જા NIN ની અંદાજિત જરૂરિયાત છે). એડેડ શુગર ઊર્જાના {#}% (ઉપલી {#}%) અને સેચ્યુરેટેડ ફેટ ઊર્જાના {#}% (WHO) છે. સોડિયમ ICMR-NIN {#} ની પુખ્ત મર્યાદા {#} મિ.ગ્રા. છે, નાના બાળકો માટે ઊર્જા મુજબ ઘટાડેલી. જે હરોળમાં જાતિ નથી તે બંનેની સરેરાશ છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('From {#} years the ICMR-NIN {#} table is by sex. On the Products and Scan pages, choose boys or girls to score for one of them; with neither chosen the average is used.', 'hi', '{#} साल से ICMR-NIN {#} की तालिका लिंग के अनुसार है। प्रोडक्ट और स्कैन पेजों पर, किसी एक के लिए स्कोर करने के लिए लड़के या लड़की चुनें; कोई न चुनने पर औसत इस्तेमाल होता है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('From {#} years the ICMR-NIN {#} table is by sex. On the Products and Scan pages, choose boys or girls to score for one of them; with neither chosen the average is used.', 'bn', '{#} বছর থেকে ICMR-NIN {#} তালিকা লিঙ্গ অনুযায়ী। প্রোডাক্ট ও স্ক্যান পেজে, একজনের জন্য স্কোর করতে ছেলে বা মেয়ে বেছে নিন; কিছু না বাছলে গড় ব্যবহার হয়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('From {#} years the ICMR-NIN {#} table is by sex. On the Products and Scan pages, choose boys or girls to score for one of them; with neither chosen the average is used.', 'gu', '{#} વર્ષથી ICMR-NIN {#} નું કોષ્ટક જાતિ મુજબ છે. પ્રોડક્ટ અને સ્કેન પેજ પર, કોઈ એક માટે સ્કોર કરવા છોકરો કે છોકરી પસંદ કરો; કોઈ ન પસંદ કરો તો સરેરાશ વપરાય છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('ICMR-NIN {#} lists {#}–{#} years for boys and girls. Choose boys or girls on the Products and Scan pages.', 'hi', 'ICMR-NIN {#} लड़कों और लड़कियों के लिए {#}–{#} साल देता है। प्रोडक्ट और स्कैन पेजों पर लड़का या लड़की चुनें।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('ICMR-NIN {#} lists {#}–{#} years for boys and girls. Choose boys or girls on the Products and Scan pages.', 'bn', 'ICMR-NIN {#} ছেলে ও মেয়েদের জন্য {#}–{#} বছর দেয়। প্রোডাক্ট ও স্ক্যান পেজে ছেলে বা মেয়ে বেছে নিন।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('ICMR-NIN {#} lists {#}–{#} years for boys and girls. Choose boys or girls on the Products and Scan pages.', 'gu', 'ICMR-NIN {#} છોકરા અને છોકરીઓ માટે {#}–{#} વર્ષ આપે છે. પ્રોડક્ટ અને સ્કેન પેજ પર છોકરો કે છોકરી પસંદ કરો.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('For adults ICMR-NIN {#} gives men and women separately, each at sedentary, moderate and heavy work. Choose men or women, and the kind of work, on the Products and Scan pages; with neither chosen the average of men and women at sedentary work is used. Pregnant and lactating women are not scored yet.', 'hi', 'वयस्कों के लिए ICMR-NIN {#} पुरुषों और महिलाओं को अलग-अलग देता है, हर एक के लिए बैठे रहने वाले, मध्यम और भारी काम पर। प्रोडक्ट और स्कैन पेजों पर पुरुष या महिला, और काम का प्रकार चुनें; कोई न चुनने पर बैठे रहने वाले काम पर पुरुषों और महिलाओं का औसत इस्तेमाल होता है। गर्भवती और स्तनपान कराने वाली महिलाओं को अभी स्कोर नहीं किया जाता।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('For adults ICMR-NIN {#} gives men and women separately, each at sedentary, moderate and heavy work. Choose men or women, and the kind of work, on the Products and Scan pages; with neither chosen the average of men and women at sedentary work is used. Pregnant and lactating women are not scored yet.', 'bn', 'প্রাপ্তবয়স্কদের জন্য ICMR-NIN {#} পুরুষ ও মহিলাদের আলাদা দেয়, প্রত্যেকের জন্য বসে থাকার, মাঝারি ও ভারী কাজে। প্রোডাক্ট ও স্ক্যান পেজে পুরুষ বা মহিলা, আর কাজের ধরন বেছে নিন; কিছু না বাছলে বসে থাকার কাজে পুরুষ ও মহিলাদের গড় ব্যবহার হয়। গর্ভবতী ও স্তন্যদানকারী মহিলাদের এখনও স্কোর করা হয় না।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('For adults ICMR-NIN {#} gives men and women separately, each at sedentary, moderate and heavy work. Choose men or women, and the kind of work, on the Products and Scan pages; with neither chosen the average of men and women at sedentary work is used. Pregnant and lactating women are not scored yet.', 'gu', 'પુખ્તો માટે ICMR-NIN {#} પુરુષો અને સ્ત્રીઓને અલગ આપે છે, દરેક માટે બેસી રહેવાના, મધ્યમ અને ભારે કામ પર. પ્રોડક્ટ અને સ્કેન પેજ પર પુરુષ કે સ્ત્રી, અને કામનો પ્રકાર પસંદ કરો; કોઈ ન પસંદ કરો તો બેસી રહેવાના કામ પર પુરુષો અને સ્ત્રીઓની સરેરાશ વપરાય છે. ગર્ભવતી અને સ્તનપાન કરાવતી સ્ત્રીઓને હજી સ્કોર થતો નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Each check below shows exactly what earns a yes and what earns a no. Count the yeses and multiply by {#} to get the score from {#} to {#}. This is why we do not trust the front of the pack: watch what is printed there against what is actually on the back.', 'hi', 'नीचे हर जाँच ठीक-ठीक बताती है कि क्या हाँ दिलाता है और क्या नहीं। हाँ गिनें और {#} से गुणा करें, {#} से {#} तक स्कोर मिलेगा। इसीलिए हम पैक के आगे के हिस्से पर भरोसा नहीं करते: देखें वहाँ क्या छपा है और पीछे असल में क्या है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Each check below shows exactly what earns a yes and what earns a no. Count the yeses and multiply by {#} to get the score from {#} to {#}. This is why we do not trust the front of the pack: watch what is printed there against what is actually on the back.', 'bn', 'নিচে প্রতিটি পরীক্ষা ঠিক কী হলে হ্যাঁ আর কী হলে না তা দেখায়। হ্যাঁ গুনুন ও {#} দিয়ে গুণ করুন, {#} থেকে {#} পর্যন্ত স্কোর পাবেন। এই কারণেই আমরা প্যাকের সামনের অংশে ভরসা করি না: দেখুন সেখানে কী ছাপা আর পেছনে আসলে কী আছে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Each check below shows exactly what earns a yes and what earns a no. Count the yeses and multiply by {#} to get the score from {#} to {#}. This is why we do not trust the front of the pack: watch what is printed there against what is actually on the back.', 'gu', 'નીચે દરેક તપાસ બરાબર બતાવે છે કે શું હા અપાવે છે અને શું ના. હા ગણો અને {#} થી ગુણો, {#} થી {#} સુધીનો સ્કોર મળશે. આથી જ અમે પેકના આગળના ભાગ પર ભરોસો કરતા નથી: જુઓ ત્યાં શું છાપ્યું છે અને પાછળ ખરેખર શું છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('"No Added<br_a/>Preservatives"', 'hi', '"बिना <br_a/>प्रिज़र्वेटिव"', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('"No Added<br_a/>Preservatives"', 'bn', '"প্রিজারভেটিভ <br_a/>ছাড়া"', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('"No Added<br_a/>Preservatives"', 'gu', '"પ્રિઝર્વેટિવ <br_a/>વગર"', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The same label can pass at one age and fail at another, so the score out of {#} changes too. Pick the age group on the <a_a>Products page</a_a> and the whole catalogue is re-scored for that age.', 'hi', 'एक ही लेबल एक उम्र में पास और दूसरी में फेल हो सकता है, इसलिए {#} में से स्कोर भी बदलता है। <a_a>प्रोडक्ट पेज</a_a> पर उम्र का समूह चुनें और पूरे कैटलॉग का उस उम्र के लिए फिर से स्कोर निकलता है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The same label can pass at one age and fail at another, so the score out of {#} changes too. Pick the age group on the <a_a>Products page</a_a> and the whole catalogue is re-scored for that age.', 'bn', 'একই লেবেল এক বয়সে পাস আর অন্য বয়সে ফেল করতে পারে, তাই {#}-এর মধ্যে স্কোরও বদলায়। <a_a>প্রোডাক্ট পেজে</a_a> বয়সের গ্রুপ বেছে নিন, পুরো ক্যাটালগের স্কোর ওই বয়সের জন্য আবার হিসাব হবে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The same label can pass at one age and fail at another, so the score out of {#} changes too. Pick the age group on the <a_a>Products page</a_a> and the whole catalogue is re-scored for that age.', 'gu', 'એ જ લેબલ એક ઉંમરે પાસ અને બીજી ઉંમરે નાપાસ થઈ શકે, તેથી {#} માંથી સ્કોર પણ બદલાય છે. <a_a>પ્રોડક્ટ પેજ</a_a> પર ઉંમર જૂથ પસંદ કરો અને આખા કેટલોગનો તે ઉંમર માટે ફરી સ્કોર કઢાય છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] ICMR-NIN (National Institute of Nutrition), "Nutrient Requirements for Indians: Recommended Dietary Allowances and Estimated Average Requirements," {#}.</b_a> The source for the energy requirement, protein RDA and dietary fibre RDA of every group on this page: children {#}–{#}, {#}–{#} and {#}–{#}; boys and girls {#}–{#}, {#}–{#} and {#}–{#}; men and women at sedentary, moderate and heavy work. It also gives the adult sodium limit of {#} mg a day ({#} g of salt), which it takes from WHO ({#}).', 'hi', '<b_a>[{#}] ICMR-NIN (राष्ट्रीय पोषण संस्थान), "भारतीयों के लिए पोषक तत्वों की आवश्यकता: अनुशंसित आहार भत्ते और अनुमानित औसत आवश्यकताएँ," {#}।</b_a> इस पेज पर हर समूह की ऊर्जा आवश्यकता, प्रोटीन RDA और आहार फाइबर RDA का स्रोत: बच्चे {#}–{#}, {#}–{#} और {#}–{#}; लड़के और लड़कियाँ {#}–{#}, {#}–{#} और {#}–{#}; पुरुष और महिलाएँ बैठे रहने वाले, मध्यम और भारी काम पर। यह प्रतिदिन {#} मि.ग्रा. (नमक {#} ग्राम) की वयस्क सोडियम सीमा भी देता है, जो WHO ({#}) से ली गई है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] ICMR-NIN (National Institute of Nutrition), "Nutrient Requirements for Indians: Recommended Dietary Allowances and Estimated Average Requirements," {#}.</b_a> The source for the energy requirement, protein RDA and dietary fibre RDA of every group on this page: children {#}–{#}, {#}–{#} and {#}–{#}; boys and girls {#}–{#}, {#}–{#} and {#}–{#}; men and women at sedentary, moderate and heavy work. It also gives the adult sodium limit of {#} mg a day ({#} g of salt), which it takes from WHO ({#}).', 'bn', '<b_a>[{#}] ICMR-NIN (জাতীয় পুষ্টি প্রতিষ্ঠান), "ভারতীয়দের জন্য পুষ্টি উপাদানের প্রয়োজন: প্রস্তাবিত খাদ্য ভাতা ও আনুমানিক গড় প্রয়োজন," {#}।</b_a> এই পেজের প্রতিটি গ্রুপের শক্তির প্রয়োজন, প্রোটিন RDA ও খাদ্যতন্তু RDA-র উৎস: শিশু {#}–{#}, {#}–{#} ও {#}–{#}; ছেলে ও মেয়ে {#}–{#}, {#}–{#} ও {#}–{#}; পুরুষ ও মহিলা বসে থাকার, মাঝারি ও ভারী কাজে। এটি দিনে {#} মিগ্রা (নুন {#} গ্রাম) প্রাপ্তবয়স্ক সোডিয়াম সীমাও দেয়, যা WHO ({#}) থেকে নেওয়া।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] ICMR-NIN (National Institute of Nutrition), "Nutrient Requirements for Indians: Recommended Dietary Allowances and Estimated Average Requirements," {#}.</b_a> The source for the energy requirement, protein RDA and dietary fibre RDA of every group on this page: children {#}–{#}, {#}–{#} and {#}–{#}; boys and girls {#}–{#}, {#}–{#} and {#}–{#}; men and women at sedentary, moderate and heavy work. It also gives the adult sodium limit of {#} mg a day ({#} g of salt), which it takes from WHO ({#}).', 'gu', '<b_a>[{#}] ICMR-NIN (રાષ્ટ્રીય પોષણ સંસ્થા), "ભારતીયો માટે પોષક તત્વોની જરૂરિયાત: ભલામણ કરેલ આહાર ભથ્થાં અને અંદાજિત સરેરાશ જરૂરિયાતો," {#}.</b_a> આ પેજ પરના દરેક જૂથની ઊર્જા જરૂરિયાત, પ્રોટીન RDA અને ફાઇબર RDA નો સ્રોત: બાળકો {#}–{#}, {#}–{#} અને {#}–{#}; છોકરા અને છોકરીઓ {#}–{#}, {#}–{#} અને {#}–{#}; પુરુષ અને સ્ત્રીઓ બેસી રહેવાના, મધ્યમ અને ભારે કામ પર. તે દિવસના {#} મિ.ગ્રા. (મીઠું {#} ગ્રામ) ની પુખ્ત સોડિયમ મર્યાદા પણ આપે છે, જે WHO ({#}) પરથી લીધી છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO, "Guideline: Sugars intake for adults and children," {#}.</b_a> Free sugars under {#}% of energy, with further benefit below {#}%. We use {#}% of each group''s energy as the daily ideal and {#}% as the upper limit, converted to grams at {#} kcal/g.', 'hi', '<b_a>[{#}] WHO, "दिशानिर्देश: वयस्कों और बच्चों में शर्करा का सेवन," {#}।</b_a> फ्री शुगर ऊर्जा के {#}% से कम, {#}% से कम पर और लाभ के साथ। हम हर समूह की ऊर्जा का {#}% दैनिक आदर्श और {#}% ऊपरी सीमा के रूप में इस्तेमाल करते हैं, {#} किलो कैलोरी/ग्राम पर ग्राम में बदलकर।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO, "Guideline: Sugars intake for adults and children," {#}.</b_a> Free sugars under {#}% of energy, with further benefit below {#}%. We use {#}% of each group''s energy as the daily ideal and {#}% as the upper limit, converted to grams at {#} kcal/g.', 'bn', '<b_a>[{#}] WHO, "নির্দেশিকা: প্রাপ্তবয়স্ক ও শিশুদের শর্করা গ্রহণ," {#}।</b_a> ফ্রি সুগার শক্তির {#}%-এর কম, {#}%-এর কমে আরও সুবিধা। আমরা প্রতিটি গ্রুপের শক্তির {#}% দৈনিক আদর্শ ও {#}% ঊর্ধ্বসীমা হিসেবে ব্যবহার করি, {#} কিলোক্যালরি/গ্রামে গ্রামে রূপান্তর করে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO, "Guideline: Sugars intake for adults and children," {#}.</b_a> Free sugars under {#}% of energy, with further benefit below {#}%. We use {#}% of each group''s energy as the daily ideal and {#}% as the upper limit, converted to grams at {#} kcal/g.', 'gu', '<b_a>[{#}] WHO, "માર્ગદર્શિકા: પુખ્તો અને બાળકોમાં શર્કરાનું સેવન," {#}.</b_a> ફ્રી શુગર ઊર્જાના {#}% થી ઓછી, {#}% થી ઓછી પર વધુ લાભ સાથે. અમે દરેક જૂથની ઊર્જાના {#}% દૈનિક આદર્શ અને {#}% ઉપલી મર્યાદા તરીકે વાપરીએ છીએ, {#} કિલોકેલરી/ગ્રામ પર ગ્રામમાં ફેરવીને.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO guidance on saturated fat</b_a> (the {#} guideline on saturated and trans fatty acid intake, and the FAO/WHO fats consultations). Saturated fat under {#}% of energy, converted to grams at {#} kcal/g.', 'hi', '<b_a>[{#}] सैचुरेटेड फैट पर WHO का मार्गदर्शन</b_a> (सैचुरेटेड और ट्रांस फैटी एसिड के सेवन पर {#} का दिशानिर्देश, और FAO/WHO वसा परामर्श)। सैचुरेटेड फैट ऊर्जा के {#}% से कम, {#} किलो कैलोरी/ग्राम पर ग्राम में बदला गया।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO guidance on saturated fat</b_a> (the {#} guideline on saturated and trans fatty acid intake, and the FAO/WHO fats consultations). Saturated fat under {#}% of energy, converted to grams at {#} kcal/g.', 'bn', '<b_a>[{#}] স্যাচুরেটেড ফ্যাট সম্পর্কে WHO-র নির্দেশনা</b_a> (স্যাচুরেটেড ও ট্রান্স ফ্যাটি অ্যাসিড গ্রহণ নিয়ে {#}-এর নির্দেশিকা, এবং FAO/WHO ফ্যাট পরামর্শ)। স্যাচুরেটেড ফ্যাট শক্তির {#}%-এর কম, {#} কিলোক্যালরি/গ্রামে গ্রামে রূপান্তরিত।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO guidance on saturated fat</b_a> (the {#} guideline on saturated and trans fatty acid intake, and the FAO/WHO fats consultations). Saturated fat under {#}% of energy, converted to grams at {#} kcal/g.', 'gu', '<b_a>[{#}] સેચ્યુરેટેડ ફેટ પર WHO નું માર્ગદર્શન</b_a> (સેચ્યુરેટેડ અને ટ્રાન્સ ફેટી એસિડના સેવન પર {#} ની માર્ગદર્શિકા, અને FAO/WHO ચરબી પરામર્શ). સેચ્યુરેટેડ ફેટ ઊર્જાના {#}% થી ઓછી, {#} કિલોકેલરી/ગ્રામ પર ગ્રામમાં ફેરવેલ.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO, "Guideline: Sodium intake for adults and children," {#}.</b_a> For children the adult limit is lowered in line with their lower energy needs. ICMR-NIN {#} gives no child figure, so we apply that rule ourselves: the {#} mg adult limit scaled by each group''s energy, about {#} mg per kcal, never above {#} mg. These child limits are our calculation, not a published figure.', 'hi', '<b_a>[{#}] WHO, "दिशानिर्देश: वयस्कों और बच्चों में सोडियम का सेवन," {#}।</b_a> बच्चों के लिए वयस्क सीमा उनकी कम ऊर्जा ज़रूरतों के अनुसार घटाई जाती है। ICMR-NIN {#} बच्चों के लिए कोई आँकड़ा नहीं देता, इसलिए हम यह नियम खुद लगाते हैं: {#} मि.ग्रा. की वयस्क सीमा को हर समूह की ऊर्जा से घटाया जाता है, लगभग {#} मि.ग्रा. प्रति किलो कैलोरी, कभी {#} मि.ग्रा. से ऊपर नहीं। ये बच्चों की सीमाएँ हमारी गणना हैं, प्रकाशित आँकड़ा नहीं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO, "Guideline: Sodium intake for adults and children," {#}.</b_a> For children the adult limit is lowered in line with their lower energy needs. ICMR-NIN {#} gives no child figure, so we apply that rule ourselves: the {#} mg adult limit scaled by each group''s energy, about {#} mg per kcal, never above {#} mg. These child limits are our calculation, not a published figure.', 'bn', '<b_a>[{#}] WHO, "নির্দেশিকা: প্রাপ্তবয়স্ক ও শিশুদের সোডিয়াম গ্রহণ," {#}।</b_a> শিশুদের জন্য প্রাপ্তবয়স্ক সীমা তাদের কম শক্তির প্রয়োজন অনুযায়ী কমানো হয়। ICMR-NIN {#} শিশুদের জন্য কোনো সংখ্যা দেয় না, তাই আমরা নিজেরাই এই নিয়ম প্রয়োগ করি: {#} মিগ্রা প্রাপ্তবয়স্ক সীমা প্রতিটি গ্রুপের শক্তি অনুযায়ী কমানো, প্রায় {#} মিগ্রা প্রতি কিলোক্যালরি, কখনও {#} মিগ্রা-র বেশি নয়। শিশুদের এই সীমাগুলো আমাদের হিসাব, প্রকাশিত সংখ্যা নয়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] WHO, "Guideline: Sodium intake for adults and children," {#}.</b_a> For children the adult limit is lowered in line with their lower energy needs. ICMR-NIN {#} gives no child figure, so we apply that rule ourselves: the {#} mg adult limit scaled by each group''s energy, about {#} mg per kcal, never above {#} mg. These child limits are our calculation, not a published figure.', 'gu', '<b_a>[{#}] WHO, "માર્ગદર્શિકા: પુખ્તો અને બાળકોમાં સોડિયમનું સેવન," {#}.</b_a> બાળકો માટે પુખ્ત મર્યાદા તેમની ઓછી ઊર્જા જરૂરિયાત મુજબ ઘટાડાય છે. ICMR-NIN {#} બાળકો માટે કોઈ આંકડો આપતું નથી, તેથી અમે આ નિયમ જાતે લગાવીએ છીએ: {#} મિ.ગ્રા. પુખ્ત મર્યાદા દરેક જૂથની ઊર્જા મુજબ ઘટાડેલી, લગભગ {#} મિ.ગ્રા. પ્રતિ કિલોકેલરી, ક્યારેય {#} મિ.ગ્રા. થી વધુ નહીં. બાળકો માટેની આ મર્યાદાઓ અમારી ગણતરી છે, પ્રકાશિત આંકડો નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI, Food Safety and Standards (Prohibition and Restrictions on Sales) Regulations.</b_a> Trans fat capped at ≤{#}% of total oils and fats in any food product, all ages, all categories.', 'hi', '<b_a>[{#}] FSSAI, खाद्य सुरक्षा और मानक (बिक्री पर प्रतिषेध और निबंधन) विनियम।</b_a> किसी भी खाद्य उत्पाद में कुल तेलों और वसा का ट्रांस फैट ≤{#}% तक सीमित, सभी उम्र, सभी श्रेणियाँ।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI, Food Safety and Standards (Prohibition and Restrictions on Sales) Regulations.</b_a> Trans fat capped at ≤{#}% of total oils and fats in any food product, all ages, all categories.', 'bn', '<b_a>[{#}] FSSAI, খাদ্য নিরাপত্তা ও মান (বিক্রয়ে নিষেধাজ্ঞা ও বিধিনিষেধ) প্রবিধান।</b_a> যেকোনো খাদ্য পণ্যে মোট তেল ও ফ্যাটের ট্রান্স ফ্যাট ≤{#}%-এ সীমিত, সব বয়স, সব বিভাগ।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI, Food Safety and Standards (Prohibition and Restrictions on Sales) Regulations.</b_a> Trans fat capped at ≤{#}% of total oils and fats in any food product, all ages, all categories.', 'gu', '<b_a>[{#}] FSSAI, ખાદ્ય સુરક્ષા અને ધોરણો (વેચાણ પર પ્રતિબંધ અને નિયંત્રણ) નિયમો.</b_a> કોઈ પણ ખાદ્ય ઉત્પાદનમાં કુલ તેલ અને ચરબીનું ટ્રાન્સ ફેટ ≤{#}% સુધી મર્યાદિત, દરેક ઉંમર, દરેક શ્રેણી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI, Food Safety and Standards (Food Products Standards and Food Additives) Regulations, {#}.</b_a> Governs permitted preservatives (Class II) and additives (colours, flavour enhancers) by INS number.', 'hi', '<b_a>[{#}] FSSAI, खाद्य सुरक्षा और मानक (खाद्य उत्पाद मानक और खाद्य योजक) विनियम, {#}।</b_a> अनुमत प्रिज़र्वेटिव (क्लास II) और योजक (रंग, फ्लेवर एन्हांसर) को INS नंबर से नियंत्रित करता है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI, Food Safety and Standards (Food Products Standards and Food Additives) Regulations, {#}.</b_a> Governs permitted preservatives (Class II) and additives (colours, flavour enhancers) by INS number.', 'bn', '<b_a>[{#}] FSSAI, খাদ্য নিরাপত্তা ও মান (খাদ্য পণ্যের মান ও খাদ্য সংযোজন) প্রবিধান, {#}।</b_a> অনুমোদিত প্রিজারভেটিভ (ক্লাস II) ও সংযোজন (রং, ফ্লেভার এনহান্সার) INS নম্বর অনুযায়ী নিয়ন্ত্রণ করে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI, Food Safety and Standards (Food Products Standards and Food Additives) Regulations, {#}.</b_a> Governs permitted preservatives (Class II) and additives (colours, flavour enhancers) by INS number.', 'gu', '<b_a>[{#}] FSSAI, ખાદ્ય સુરક્ષા અને ધોરણો (ખાદ્ય ઉત્પાદન ધોરણો અને ખાદ્ય ઉમેરણો) નિયમો, {#}.</b_a> માન્ય પ્રિઝર્વેટિવ (ક્લાસ II) અને ઉમેરણો (રંગ, ફ્લેવર એન્હાન્સર) ને INS નંબર દ્વારા નિયંત્રિત કરે છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI compliance affidavit, Supreme Court of India, W.P.(C) No. {#}/{#} — {#}S and Our Health Society vs Union of India, filed {#} August {#}.</b_a> Proposes a front-of-pack red hexagon warning for foods high in added saturated fat, added sugar, and/or salt (HFSS), with thresholds to be drawn from the <i_b>Dietary Guidelines for Indians, {#}</i_b> (ICMR-NIN). This is a live, pending proceeding — not yet a notified regulation.', 'hi', '<b_a>[{#}] FSSAI अनुपालन हलफ़नामा, भारत का सर्वोच्च न्यायालय, W.P.(C) सं. {#}/{#} — {#}S और हमारी स्वास्थ्य सोसाइटी बनाम भारत संघ, {#} अगस्त {#} को दायर।</b_a> ज़्यादा सैचुरेटेड फैट, एडेड शुगर और/या नमक (HFSS) वाले खाने के लिए पैक के आगे लाल षट्कोण चेतावनी का प्रस्ताव, जिसकी सीमाएँ <i_b>भारतीयों के लिए आहार दिशानिर्देश, {#}</i_b> (ICMR-NIN) से ली जाएँगी। यह एक जारी, लंबित कार्यवाही है, अभी अधिसूचित नियम नहीं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI compliance affidavit, Supreme Court of India, W.P.(C) No. {#}/{#} — {#}S and Our Health Society vs Union of India, filed {#} August {#}.</b_a> Proposes a front-of-pack red hexagon warning for foods high in added saturated fat, added sugar, and/or salt (HFSS), with thresholds to be drawn from the <i_b>Dietary Guidelines for Indians, {#}</i_b> (ICMR-NIN). This is a live, pending proceeding — not yet a notified regulation.', 'bn', '<b_a>[{#}] FSSAI সম্মতি হলফনামা, ভারতের সুপ্রিম কোর্ট, W.P.(C) নং {#}/{#} — {#}S ও আমাদের স্বাস্থ্য সোসাইটি বনাম ভারত সরকার, {#} আগস্ট {#} দাখিল।</b_a> বেশি স্যাচুরেটেড ফ্যাট, অ্যাডেড সুগার এবং/বা নুনের (HFSS) খাবারের জন্য প্যাকের সামনে লাল ষড়ভুজ সতর্কতার প্রস্তাব, যার সীমা <i_b>ভারতীয়দের জন্য খাদ্য নির্দেশিকা, {#}</i_b> (ICMR-NIN) থেকে নেওয়া হবে। এটি একটি চলমান, বিচারাধীন কার্যক্রম, এখনও বিজ্ঞাপিত নিয়ম নয়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] FSSAI compliance affidavit, Supreme Court of India, W.P.(C) No. {#}/{#} — {#}S and Our Health Society vs Union of India, filed {#} August {#}.</b_a> Proposes a front-of-pack red hexagon warning for foods high in added saturated fat, added sugar, and/or salt (HFSS), with thresholds to be drawn from the <i_b>Dietary Guidelines for Indians, {#}</i_b> (ICMR-NIN). This is a live, pending proceeding — not yet a notified regulation.', 'gu', '<b_a>[{#}] FSSAI અનુપાલન સોગંદનામું, ભારતની સર્વોચ્ચ અદાલત, W.P.(C) નં. {#}/{#} — {#}S અને અમારી સ્વાસ્થ્ય સોસાયટી વિરુદ્ધ ભારત સંઘ, {#} ઓગસ્ટ {#} ના રોજ દાખલ.</b_a> વધુ સેચ્યુરેટેડ ફેટ, એડેડ શુગર અને/અથવા મીઠા (HFSS) વાળા ખોરાક માટે પેકના આગળ લાલ ષટ્કોણ ચેતવણીનો પ્રસ્તાવ, જેની મર્યાદાઓ <i_b>ભારતીયો માટે આહાર માર્ગદર્શિકા, {#}</i_b> (ICMR-NIN) પરથી લેવાશે. આ ચાલુ, બાકી કાર્યવાહી છે, હજી જાહેર કરાયેલો નિયમ નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] Serving sizes.</b_a> The serving printed on the pack. Where a pack prints none, a reference amount for that kind of food, taken from the US FDA''s "reference amounts customarily consumed" ({#} CFR {#}) where one fits, and our own estimate where none does.', 'hi', '<b_a>[{#}] सर्विंग साइज़।</b_a> पैक पर छपी सर्विंग। जहाँ पैक पर कुछ नहीं छपा, वहाँ उस तरह के खाने की संदर्भ मात्रा, जहाँ एक फिट बैठे वहाँ US FDA की "आम तौर पर खाई जाने वाली संदर्भ मात्रा" ({#} CFR {#}) से, और जहाँ कोई नहीं बैठती वहाँ हमारा अपना अनुमान।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] Serving sizes.</b_a> The serving printed on the pack. Where a pack prints none, a reference amount for that kind of food, taken from the US FDA''s "reference amounts customarily consumed" ({#} CFR {#}) where one fits, and our own estimate where none does.', 'bn', '<b_a>[{#}] সার্ভিং সাইজ।</b_a> প্যাকে ছাপা সার্ভিং। যেখানে প্যাকে কিছু ছাপা নেই, সেখানে ওই ধরনের খাবারের রেফারেন্স পরিমাণ, যেখানে একটি মানায় সেখানে US FDA-এর "সাধারণত খাওয়া রেফারেন্স পরিমাণ" ({#} CFR {#}) থেকে, আর যেখানে কোনোটি মানায় না সেখানে আমাদের নিজস্ব অনুমান।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>[{#}] Serving sizes.</b_a> The serving printed on the pack. Where a pack prints none, a reference amount for that kind of food, taken from the US FDA''s "reference amounts customarily consumed" ({#} CFR {#}) where one fits, and our own estimate where none does.', 'gu', '<b_a>[{#}] સર્વિંગ સાઇઝ.</b_a> પેક પર છાપેલ સર્વિંગ. જ્યાં પેક પર કંઈ છાપેલ નથી, ત્યાં તે પ્રકારના ખોરાકની સંદર્ભ માત્રા, જ્યાં એક બંધબેસે ત્યાં US FDA ની "સામાન્ય રીતે ખવાતી સંદર્ભ માત્રા" ({#} CFR {#}) પરથી, અને જ્યાં કોઈ ન બંધબેસે ત્યાં અમારો પોતાનો અંદાજ.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>What is a citation and what is our own judgment:</b_a> the daily references behind checks {#}, {#}, {#}, {#} and {#} come from [{#}] to [{#}], except the child sodium limit, which is our scaling of [{#}] (see [{#}]). Checks {#}, {#} and {#} test the ingredient list against FSSAI rules [{#}] and [{#}]. Check {#} echoes the high-in-fat-sugar-or-salt idea in [{#}], but the rule itself is ours. These parts are our own choices, applied the same way every time: the line a serving must stay under ({#}% of the day, {#}% for snacks, sweets and sweet drinks) to pass sugar, sodium and saturated fat; the {#}% of the day a serving must give to pass fibre and protein; the base-ingredient check ({#}); which foods count as snacks; and holding a pack at OK when a risk check fails. The {#}% line is also the one the UK''s traffic-light labels use for a portion. Under {#} months there is no published reference band, so the {#} to {#} year reference is used. Pregnant and lactating women and the elderly are not scored yet.', 'hi', '<b_a>क्या उद्धरण है और क्या हमारा अपना निर्णय:</b_a> जाँच {#}, {#}, {#}, {#} और {#} के पीछे के दैनिक संदर्भ [{#}] से [{#}] तक से आते हैं, सिवाय बच्चों की सोडियम सीमा के, जो [{#}] का हमारा अनुपात है (देखें [{#}])। जाँच {#}, {#} और {#} सामग्री की सूची को FSSAI नियमों [{#}] और [{#}] से परखती हैं। जाँच {#} [{#}] के ज़्यादा-वसा-चीनी-या-नमक वाले विचार से मेल खाती है, पर नियम खुद हमारा है। ये हिस्से हमारे अपने चुनाव हैं, हर बार एक ही तरह लागू: वह रेखा जिसके नीचे एक सर्विंग को चीनी, सोडियम और सैचुरेटेड फैट में पास होने के लिए रहना है (दिन का {#}%, स्नैक्स, मिठाइयों और मीठे पेयों के लिए {#}%); दिन का वह {#}% जो एक सर्विंग को फाइबर और प्रोटीन में पास होने के लिए देना है; मुख्य सामग्री की जाँच ({#}); कौन-से खाने स्नैक्स गिने जाएँ; और जोखिम जाँच फेल होने पर पैक को ठीक पर रोकना। {#}% की रेखा वही है जो UK के ट्रैफ़िक-लाइट लेबल एक हिस्से के लिए इस्तेमाल करते हैं। {#} महीने से कम के लिए कोई प्रकाशित संदर्भ समूह नहीं है, इसलिए {#} से {#} साल का संदर्भ इस्तेमाल होता है। गर्भवती और स्तनपान कराने वाली महिलाओं और बुज़ुर्गों को अभी स्कोर नहीं किया जाता।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>What is a citation and what is our own judgment:</b_a> the daily references behind checks {#}, {#}, {#}, {#} and {#} come from [{#}] to [{#}], except the child sodium limit, which is our scaling of [{#}] (see [{#}]). Checks {#}, {#} and {#} test the ingredient list against FSSAI rules [{#}] and [{#}]. Check {#} echoes the high-in-fat-sugar-or-salt idea in [{#}], but the rule itself is ours. These parts are our own choices, applied the same way every time: the line a serving must stay under ({#}% of the day, {#}% for snacks, sweets and sweet drinks) to pass sugar, sodium and saturated fat; the {#}% of the day a serving must give to pass fibre and protein; the base-ingredient check ({#}); which foods count as snacks; and holding a pack at OK when a risk check fails. The {#}% line is also the one the UK''s traffic-light labels use for a portion. Under {#} months there is no published reference band, so the {#} to {#} year reference is used. Pregnant and lactating women and the elderly are not scored yet.', 'bn', '<b_a>কোনটি উদ্ধৃতি আর কোনটি আমাদের নিজস্ব বিচার:</b_a> পরীক্ষা {#}, {#}, {#}, {#} ও {#}-এর পেছনের দৈনিক রেফারেন্স [{#}] থেকে [{#}] পর্যন্ত থেকে আসে, শুধু শিশুদের সোডিয়াম সীমা বাদে, যা [{#}]-এর আমাদের অনুপাত (দেখুন [{#}])। পরীক্ষা {#}, {#} ও {#} উপকরণের তালিকাকে FSSAI নিয়ম [{#}] ও [{#}] দিয়ে যাচাই করে। পরীক্ষা {#} [{#}]-এর বেশি-ফ্যাট-চিনি-বা-নুনের ধারণার সঙ্গে মেলে, কিন্তু নিয়মটি নিজেই আমাদের। এই অংশগুলো আমাদের নিজস্ব সিদ্ধান্ত, প্রতিবার একইভাবে প্রযোগ: যে রেখার নিচে এক সার্ভিংকে চিনি, সোডিয়াম ও স্যাচুরেটেড ফ্যাটে পাস করতে থাকতে হবে (দিনের {#}%, স্ন্যাকস, মিষ্টি ও মিষ্টি পানীয়ের জন্য {#}%); দিনের যে {#}% এক সার্ভিংকে ফাইবার ও প্রোটিনে পাস করতে দিতে হবে; মূল উপকরণের পরীক্ষা ({#}); কোন খাবার স্ন্যাকস গণ্য হবে; এবং ঝুঁকির পরীক্ষা ফেল করলে প্যাককে মোটামুটিতে আটকানো। {#}%-এর রেখাটি সেটাই যা UK-র ট্রাফিক-লাইট লেবেল এক অংশের জন্য ব্যবহার করে। {#} মাসের কমের জন্য কোনো প্রকাশিত রেফারেন্স গ্রুপ নেই, তাই {#} থেকে {#} বছরের রেফারেন্স ব্যবহার হয়। গর্ভবতী ও স্তন্যদানকারী মহিলা এবং বয়স্কদের এখনও স্কোর করা হয় না।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>What is a citation and what is our own judgment:</b_a> the daily references behind checks {#}, {#}, {#}, {#} and {#} come from [{#}] to [{#}], except the child sodium limit, which is our scaling of [{#}] (see [{#}]). Checks {#}, {#} and {#} test the ingredient list against FSSAI rules [{#}] and [{#}]. Check {#} echoes the high-in-fat-sugar-or-salt idea in [{#}], but the rule itself is ours. These parts are our own choices, applied the same way every time: the line a serving must stay under ({#}% of the day, {#}% for snacks, sweets and sweet drinks) to pass sugar, sodium and saturated fat; the {#}% of the day a serving must give to pass fibre and protein; the base-ingredient check ({#}); which foods count as snacks; and holding a pack at OK when a risk check fails. The {#}% line is also the one the UK''s traffic-light labels use for a portion. Under {#} months there is no published reference band, so the {#} to {#} year reference is used. Pregnant and lactating women and the elderly are not scored yet.', 'gu', '<b_a>શું ટાંકેલું છે અને શું અમારો પોતાનો નિર્ણય:</b_a> તપાસ {#}, {#}, {#}, {#} અને {#} પાછળના દૈનિક સંદર્ભો [{#}] થી [{#}] સુધીથી આવે છે, સિવાય કે બાળકોની સોડિયમ મર્યાદા, જે [{#}] નું અમારું પ્રમાણ છે (જુઓ [{#}]). તપાસ {#}, {#} અને {#} સામગ્રીની યાદીને FSSAI નિયમો [{#}] અને [{#}] સામે ચકાસે છે. તપાસ {#} [{#}] ના વધુ-ચરબી-ખાંડ-કે-મીઠાના વિચાર સાથે મળે છે, પણ નિયમ પોતે અમારો છે. આ ભાગો અમારી પોતાની પસંદગી છે, દર વખતે એ જ રીતે લાગુ: તે રેખા જેની નીચે એક સર્વિંગે ખાંડ, સોડિયમ અને સેચ્યુરેટેડ ફેટમાં પાસ થવા રહેવું પડે (દિવસના {#}%, સ્નૅક્સ, મીઠાઈ અને મીઠા પીણાં માટે {#}%); દિવસનો તે {#}% જે એક સર્વિંગે ફાઇબર અને પ્રોટીનમાં પાસ થવા આપવો પડે; મુખ્ય સામગ્રીની તપાસ ({#}); કયા ખોરાક સ્નૅક્સ ગણાય; અને જોખમ તપાસ નાપાસ થાય ત્યારે પેકને ઠીક પર રોકવો. {#}% ની રેખા એ જ છે જે UK ના ટ્રાફિક-લાઇટ લેબલ એક ભાગ માટે વાપરે છે. {#} મહિનાથી ઓછા માટે કોઈ પ્રકાશિત સંદર્ભ જૂથ નથી, તેથી {#} થી {#} વર્ષનો સંદર્ભ વપરાય છે. ગર્ભવતી અને સ્તનપાન કરાવતી સ્ત્રીઓ અને વૃદ્ધોને હજી સ્કોર થતો નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a>, <b_b>WHO</b_b> guidance and <b_c>FSSAI</b_c> regulation · Poshan Score is an independent rating, not a certification', 'hi', '<b_a>ICMR-NIN {#}</b_a>, <b_b>WHO</b_b> के मार्गदर्शन और <b_c>FSSAI</b_c> के नियमन के मानक पर · Poshan Score एक स्वतंत्र रेटिंग है, कोई प्रमाणन नहीं', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a>, <b_b>WHO</b_b> guidance and <b_c>FSSAI</b_c> regulation · Poshan Score is an independent rating, not a certification', 'bn', '<b_a>ICMR-NIN {#}</b_a>, <b_b>WHO</b_b>-র নির্দেশনা ও <b_c>FSSAI</b_c>-এর নিয়ন্ত্রণের মানদণ্ডে · Poshan Score একটি স্বাধীন রেটিং, কোনো সার্টিফিকেশন নয়', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a>, <b_b>WHO</b_b> guidance and <b_c>FSSAI</b_c> regulation · Poshan Score is an independent rating, not a certification', 'gu', '<b_a>ICMR-NIN {#}</b_a>, <b_b>WHO</b_b> ના માર્ગદર્શન અને <b_c>FSSAI</b_c> ના નિયમનના ધોરણ પર · Poshan Score એક સ્વતંત્ર રેટિંગ છે, પ્રમાણપત્ર નથી', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Why we built the Poshan Score: a plain, independent way to read what is really on the back of a pack, scored for each age group from {#} months to adults.', 'hi', 'हमने Poshan Score क्यों बनाया: पैक के पीछे असल में क्या है, यह पढ़ने का एक सरल, स्वतंत्र तरीका, {#} महीने से वयस्कों तक हर उम्र समूह के लिए स्कोर के साथ।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Why we built the Poshan Score: a plain, independent way to read what is really on the back of a pack, scored for each age group from {#} months to adults.', 'bn', 'আমরা কেন Poshan Score বানালাম: প্যাকের পেছনে আসলে কী আছে তা পড়ার একটি সরল, স্বাধীন উপায়, {#} মাস থেকে প্রাপ্তবয়স্ক পর্যন্ত প্রতিটি বয়সের গ্রুপের জন্য স্কোরসহ।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Why we built the Poshan Score: a plain, independent way to read what is really on the back of a pack, scored for each age group from {#} months to adults.', 'gu', 'અમે Poshan Score કેમ બનાવ્યો: પેકની પાછળ ખરેખર શું છે તે વાંચવાની એક સરળ, સ્વતંત્ર રીત, {#} મહિનાથી પુખ્ત સુધી દરેક ઉંમર જૂથ માટે સ્કોર સાથે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This started as a parent''s habit before it became a rubric. Here''s the version without the spreadsheets, the age bands, or the citations.', 'hi', 'यह एक अभिभावक की आदत के रूप में शुरू हुआ, रूब्रिक बनने से पहले। यह रहा बिना स्प्रेडशीट, उम्र के समूहों या उद्धरणों वाला संस्करण।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This started as a parent''s habit before it became a rubric. Here''s the version without the spreadsheets, the age bands, or the citations.', 'bn', 'এটি শুরু হয়েছিল একজন অভিভাবকের অভ্যাস হিসেবে, রুব্রিক হওয়ার আগে। এই হল স্প্রেডশিট, বয়সের গ্রুপ বা উদ্ধৃতি ছাড়া সংস্করণ।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('This started as a parent''s habit before it became a rubric. Here''s the version without the spreadsheets, the age bands, or the citations.', 'gu', 'આ એક વાલીની આદત તરીકે શરૂ થયું, રૂબ્રિક બનતા પહેલાં. આ છે સ્પ્રેડશીટ, ઉંમર જૂથો કે ટાંકણ વગરનું સંસ્કરણ.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Feeding kids well felt, for a long time, like it came down to reading the front of a box. "No added sugar." "Rich in fibre." "Trusted by nutritionists." I believed the front the way most parents do — because turning a pack over and reading nine lines of ingredient text in six-point type isn''t something anyone has the time or patience for, standing in an aisle with a child pulling at your sleeve.', 'hi', 'बच्चों को अच्छा खिलाना, बहुत समय तक, डिब्बे का आगे का हिस्सा पढ़ने जैसा लगता रहा। "कोई एडेड शुगर नहीं।" "फाइबर से भरपूर।" "न्यूट्रिशनिस्टों का भरोसा।" मैं आगे के हिस्से पर वैसे ही भरोसा करता था जैसे ज़्यादातर अभिभावक करते हैं, क्योंकि पैक को पलटकर छह पॉइंट के छोटे अक्षरों में नौ पंक्तियों की सामग्री पढ़ना ऐसी चीज़ नहीं जिसके लिए किसी के पास समय या धैर्य हो, गली में खड़े होकर, जब बच्चा आस्तीन खींच रहा हो।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Feeding kids well felt, for a long time, like it came down to reading the front of a box. "No added sugar." "Rich in fibre." "Trusted by nutritionists." I believed the front the way most parents do — because turning a pack over and reading nine lines of ingredient text in six-point type isn''t something anyone has the time or patience for, standing in an aisle with a child pulling at your sleeve.', 'bn', 'বাচ্চাদের ভালো খাওয়ানো অনেকদিন ধরে বাক্সের সামনের অংশ পড়ার মতোই মনে হত। "কোনো অ্যাডেড সুগার নেই।" "ফাইবারে ভরপুর।" "পুষ্টিবিদদের ভরসা।" আমি সামনের অংশে সেভাবেই ভরসা করতাম যেভাবে বেশিরভাগ অভিভাবক করেন, কারণ প্যাক উল্টে ছয় পয়েন্টের ছোট অক্ষরে নয় লাইনের উপকরণ পড়া এমন কিছু নয় যার জন্য কারও সময় বা ধৈর্য আছে, গলিতে দাঁড়িয়ে, যখন শিশু আস্তিন টানছে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Feeding kids well felt, for a long time, like it came down to reading the front of a box. "No added sugar." "Rich in fibre." "Trusted by nutritionists." I believed the front the way most parents do — because turning a pack over and reading nine lines of ingredient text in six-point type isn''t something anyone has the time or patience for, standing in an aisle with a child pulling at your sleeve.', 'gu', 'બાળકોને સારું ખવડાવવું, લાંબા સમય સુધી, ડબ્બાનો આગળનો ભાગ વાંચવા જેવું લાગતું રહ્યું. "કોઈ એડેડ શુગર નહીં." "ફાઇબરથી ભરપૂર." "ન્યુટ્રિશનિસ્ટોનો ભરોસો." હું આગળના ભાગ પર એ જ રીતે ભરોસો કરતો જેમ મોટાભાગના વાલીઓ કરે છે, કારણ કે પેકને ઉલટાવીને છ પૉઇન્ટના નાના અક્ષરોમાં નવ લીટીની સામગ્રી વાંચવી એવી વસ્તુ નથી જેના માટે કોઈ પાસે સમય કે ધીરજ હોય, ગલીમાં ઊભા રહીને, જ્યારે બાળક બાંય ખેંચી રહ્યું હોય.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Not out of suspicion at first — more out of habit, the way you check a price tag twice. And the gap between what the front claimed and what the ingredient panel actually said kept showing up in places I didn''t expect. A "wholesome" muesli with sugar sitting a few ingredients down the list. A ketchup where tomato wasn''t even the first thing named. A seasoning sachet whose printed "serving size" was so small that the sodium math only looked reasonable if nobody actually used a full sachet in a meal.', 'hi', 'शुरू में शक से नहीं, बल्कि आदत से, जैसे आप कीमत का टैग दो बार जाँचते हैं। और आगे जो दावा था और सामग्री की पट्टी में असल में जो लिखा था, उनके बीच का फ़र्क़ उन जगहों पर दिखता रहा जिनकी मुझे उम्मीद नहीं थी। एक "पौष्टिक" म्यूसली जिसकी सूची में कुछ सामग्री नीचे चीनी बैठी थी। एक केचप जिसमें टमाटर पहला नाम तक नहीं था। एक मसाले का पैकेट जिसका छपा "सर्विंग साइज़" इतना छोटा था कि सोडियम का हिसाब तभी ठीक लगता था जब कोई खाने में पूरा पैकेट इस्तेमाल न करे।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Not out of suspicion at first — more out of habit, the way you check a price tag twice. And the gap between what the front claimed and what the ingredient panel actually said kept showing up in places I didn''t expect. A "wholesome" muesli with sugar sitting a few ingredients down the list. A ketchup where tomato wasn''t even the first thing named. A seasoning sachet whose printed "serving size" was so small that the sodium math only looked reasonable if nobody actually used a full sachet in a meal.', 'bn', 'প্রথমে সন্দেহ থেকে নয়, বরং অভ্যাস থেকে, যেমন আপনি দামের ট্যাগ দুবার দেখেন। আর সামনে যা দাবি ছিল আর উপকরণের প্যানেলে আসলে যা লেখা ছিল, তার ফারাক এমন জায়গায় দেখা যেতে থাকল যা আমি আশা করিনি। একটি "পুষ্টিকর" মুসেলি যার তালিকায় কয়েক উপকরণ নিচে চিনি বসে ছিল। একটি কেচাপ যাতে টমেটো প্রথম নামও ছিল না। একটি মশলার প্যাকেট যার ছাপা "সার্ভিং সাইজ" এত ছোট ছিল যে সোডিয়ামের হিসাব তখনই ঠিক মনে হত যদি কেউ খাবারে পুরো প্যাকেট ব্যবহার না করে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Not out of suspicion at first — more out of habit, the way you check a price tag twice. And the gap between what the front claimed and what the ingredient panel actually said kept showing up in places I didn''t expect. A "wholesome" muesli with sugar sitting a few ingredients down the list. A ketchup where tomato wasn''t even the first thing named. A seasoning sachet whose printed "serving size" was so small that the sodium math only looked reasonable if nobody actually used a full sachet in a meal.', 'gu', 'શરૂઆતમાં શંકાથી નહીં, પણ આદતથી, જેમ તમે ભાવનું ટૅગ બે વાર તપાસો છો. અને આગળ જે દાવો હતો અને સામગ્રીની પટ્ટીમાં ખરેખર જે લખ્યું હતું, તેમની વચ્ચેનો તફાવત એવી જગ્યાએ દેખાતો રહ્યો જેની મને અપેક્ષા નહોતી. એક "પૌષ્ટિક" મ્યુસલી જેની યાદીમાં થોડી સામગ્રી નીચે ખાંડ બેઠી હતી. એક કેચઅપ જેમાં ટામેટું પહેલું નામ પણ નહોતું. એક મસાલાનું પેકેટ જેની છાપેલી "સર્વિંગ સાઇઝ" એટલી નાની હતી કે સોડિયમનો હિસાબ ત્યારે જ બરાબર લાગતો જ્યારે કોઈ ભોજનમાં આખું પેકેટ વાપરે નહીં.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('"The label wasn''t lying. It just wasn''t written for someone standing in an aisle with fifteen seconds and a tired kid."', 'hi', '"लेबल झूठ नहीं बोल रहा था। वह बस उस इंसान के लिए नहीं लिखा गया था जो पंद्रह सेकंड और एक थके हुए बच्चे के साथ गली में खड़ा है।"', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('"The label wasn''t lying. It just wasn''t written for someone standing in an aisle with fifteen seconds and a tired kid."', 'bn', '"লেবেল মিথ্যা বলছিল না। সেটা শুধু এমন কারও জন্য লেখা হয়নি যে পনেরো সেকেন্ড আর একটি ক্লান্ত শিশুকে নিয়ে গলিতে দাঁড়িয়ে আছে।"', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('"The label wasn''t lying. It just wasn''t written for someone standing in an aisle with fifteen seconds and a tired kid."', 'gu', '"લેબલ જૂઠું નહોતું બોલતું. તે બસ એવા કોઈ માટે લખાયેલું નહોતું જે પંદર સેકન્ડ અને એક થાકેલા બાળક સાથે ગલીમાં ઊભું હોય."', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Everything I kept finding was printed, in compliance with the law, in the correct font size. This wasn''t a story about brands breaking rules — it was a story about how much a food label can get away with saying, technically, truthfully, while still leaving a parent with the wrong picture of what''s actually going into their child. <b_a>The rules were being followed. The point was still being missed.</b_a>', 'hi', 'मुझे जो कुछ मिलता रहा वह सब कानून के अनुसार, सही फ़ॉन्ट साइज़ में छपा था। यह ब्रांडों के नियम तोड़ने की कहानी नहीं थी: यह इस बात की कहानी थी कि खाने का लेबल तकनीकी रूप से, सच्चाई से, कितना कुछ कह सकता है और फिर भी अभिभावक के मन में गलत तस्वीर छोड़ सकता है कि उनके बच्चे के अंदर असल में क्या जा रहा है। <b_a>नियमों का पालन हो रहा था। मुद्दा फिर भी छूट रहा था।</b_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Everything I kept finding was printed, in compliance with the law, in the correct font size. This wasn''t a story about brands breaking rules — it was a story about how much a food label can get away with saying, technically, truthfully, while still leaving a parent with the wrong picture of what''s actually going into their child. <b_a>The rules were being followed. The point was still being missed.</b_a>', 'bn', 'আমি যা কিছু পেতে থাকলাম সবই আইন মেনে, সঠিক ফন্ট সাইজে ছাপা ছিল। এটা ব্র্যান্ডের নিয়ম ভাঙার গল্প ছিল না: এটা ছিল খাবারের লেবেল প্রযুক্তিগতভাবে, সত্য কথায়, কতটা বলতে পারে আর তবুও অভিভাবকের মনে ভুল ছবি রেখে যেতে পারে যে তাঁদের সন্তানের ভেতরে আসলে কী যাচ্ছে সে সম্পর্কে। <b_a>নিয়ম মানা হচ্ছিল। মূল কথাটা তবুও ছুটে যাচ্ছিল।</b_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Everything I kept finding was printed, in compliance with the law, in the correct font size. This wasn''t a story about brands breaking rules — it was a story about how much a food label can get away with saying, technically, truthfully, while still leaving a parent with the wrong picture of what''s actually going into their child. <b_a>The rules were being followed. The point was still being missed.</b_a>', 'gu', 'મને જે કંઈ મળતું રહ્યું તે બધું કાયદા મુજબ, સાચા ફૉન્ટ સાઇઝમાં છપાયેલું હતું. આ બ્રાન્ડો દ્વારા નિયમ તોડવાની વાર્તા નહોતી: આ એ વાર્તા હતી કે ખોરાકનું લેબલ તકનીકી રીતે, સાચી રીતે, કેટલું બધું કહી શકે છે અને છતાં વાલીના મનમાં તેમના બાળકની અંદર ખરેખર શું જઈ રહ્યું છે તેનું ખોટું ચિત્ર છોડી શકે છે. <b_a>નિયમોનું પાલન થઈ રહ્યું હતું. મુદ્દો હજી પણ ચૂકાઈ રહ્યો હતો.</b_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('There''s enough of that already — inconsistent from one Instagram post to the next, and rarely benchmarked against anything more solid than a personal preference. What I wanted was the same numbers, read the same way, every time, checked against something real — <b_a>ICMR-NIN''s dietary guidelines, FSSAI''s own regulations</b_a> — instead of a brand''s marketing copy. And I wanted our own products held to that same bar, not just everyone else''s on the shelf.', 'hi', 'इस तरह की बातें पहले से काफ़ी हैं: एक इंस्टाग्राम पोस्ट से दूसरी तक बदलती, और शायद ही कभी निजी पसंद से ज़्यादा ठोस किसी चीज़ के विरुद्ध जाँची गई। मैं चाहता था कि वही संख्याएँ, एक ही तरह पढ़ी जाएँ, हर बार, किसी असली चीज़ के विरुद्ध जाँची हुई: <b_a>ICMR-NIN के आहार दिशानिर्देश, FSSAI के अपने नियम</b_a>, किसी ब्रांड की मार्केटिंग के बजाय। और मैं चाहता था कि हमारे अपने प्रोडक्ट भी उसी पैमाने पर रखे जाएँ, सिर्फ़ शेल्फ़ पर बाकी सबके नहीं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('There''s enough of that already — inconsistent from one Instagram post to the next, and rarely benchmarked against anything more solid than a personal preference. What I wanted was the same numbers, read the same way, every time, checked against something real — <b_a>ICMR-NIN''s dietary guidelines, FSSAI''s own regulations</b_a> — instead of a brand''s marketing copy. And I wanted our own products held to that same bar, not just everyone else''s on the shelf.', 'bn', 'এই ধরনের কথা আগে থেকেই যথেষ্ট আছে: এক ইনস্টাগ্রাম পোস্ট থেকে আরেকটিতে বদলে যায়, আর ব্যক্তিগত পছন্দের চেয়ে শক্ত কিছুর বিরুদ্ধে খুব কমই যাচাই হয়। আমি চেয়েছিলাম একই সংখ্যা, একইভাবে পড়া, প্রতিবার, কোনো আসল জিনিসের বিরুদ্ধে যাচাই করা: <b_a>ICMR-NIN-এর খাদ্য নির্দেশিকা, FSSAI-এর নিজস্ব নিয়ম</b_a>, কোনো ব্র্যান্ডের মার্কেটিংয়ের বদলে। আর আমি চেয়েছিলাম আমাদের নিজেদের প্রোডাক্টও একই মাপকাঠিতে রাখা হোক, শুধু তাকে থাকা বাকিদের নয়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('There''s enough of that already — inconsistent from one Instagram post to the next, and rarely benchmarked against anything more solid than a personal preference. What I wanted was the same numbers, read the same way, every time, checked against something real — <b_a>ICMR-NIN''s dietary guidelines, FSSAI''s own regulations</b_a> — instead of a brand''s marketing copy. And I wanted our own products held to that same bar, not just everyone else''s on the shelf.', 'gu', 'આ પ્રકારની વાતો પહેલેથી પૂરતી છે: એક ઇન્સ્ટાગ્રામ પોસ્ટથી બીજી સુધી બદલાતી, અને ભાગ્યે જ વ્યક્તિગત પસંદગી કરતાં વધુ ઠોસ કોઈ વસ્તુ સામે ચકાસાયેલી. મારે એ જ સંખ્યાઓ, એ જ રીતે વંચાયેલી, દર વખતે, કોઈ સાચી વસ્તુ સામે ચકાસેલી જોઈતી હતી: <b_a>ICMR-NIN ની આહાર માર્ગદર્શિકા, FSSAI ના પોતાના નિયમો</b_a>, કોઈ બ્રાન્ડના માર્કેટિંગને બદલે. અને મારે અમારા પોતાના પ્રોડક્ટ પણ એ જ ધોરણે મૂકાય તેવું જોઈતું હતું, ફક્ત શેલ્ફ પરના બીજા બધાના નહીં.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('It''s the same thing I was already doing at the shelf, turned into a rubric instead of kept in my head — ten numbers, the age bands they actually apply to, and the citations behind each one. It won''t tell you what to feed your kids. That''s still your call, and it should stay that way. It''ll just tell you, plainly, what''s actually in the pack before you decide.', 'hi', 'यह वही चीज़ है जो मैं पहले से शेल्फ़ पर कर रहा था, दिमाग में रखने के बजाय एक रूब्रिक में बदली हुई: दस संख्याएँ, वे उम्र के समूह जिन पर वे असल में लागू होती हैं, और हर एक के पीछे के उद्धरण। यह आपको नहीं बताएगा कि अपने बच्चों को क्या खिलाएँ। वह अब भी आपका फ़ैसला है, और वैसा ही रहना चाहिए। यह बस आपको सीधे-सीधे बताएगा कि फ़ैसले से पहले पैक में असल में क्या है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('It''s the same thing I was already doing at the shelf, turned into a rubric instead of kept in my head — ten numbers, the age bands they actually apply to, and the citations behind each one. It won''t tell you what to feed your kids. That''s still your call, and it should stay that way. It''ll just tell you, plainly, what''s actually in the pack before you decide.', 'bn', 'এটা সেই জিনিসই যা আমি আগে থেকে তাকের সামনে করছিলাম, মাথায় রাখার বদলে একটি রুব্রিকে পরিণত: দশটি সংখ্যা, যে বয়সের গ্রুপে সেগুলো আসলে প্রযোজ্য, আর প্রতিটির পেছনের উদ্ধৃতি। এটা আপনাকে বলবে না আপনার সন্তানদের কী খাওয়াবেন। সেটা এখনও আপনার সিদ্ধান্ত, আর তাই থাকা উচিত। এটা শুধু আপনাকে সরাসরি বলবে সিদ্ধান্তের আগে প্যাকে আসলে কী আছে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('It''s the same thing I was already doing at the shelf, turned into a rubric instead of kept in my head — ten numbers, the age bands they actually apply to, and the citations behind each one. It won''t tell you what to feed your kids. That''s still your call, and it should stay that way. It''ll just tell you, plainly, what''s actually in the pack before you decide.', 'gu', 'આ એ જ વસ્તુ છે જે હું પહેલેથી શેલ્ફ પર કરી રહ્યો હતો, મનમાં રાખવાને બદલે એક રૂબ્રિકમાં ફેરવેલી: દસ સંખ્યાઓ, જે ઉંમર જૂથો પર તે ખરેખર લાગુ પડે છે, અને દરેક પાછળના ટાંકણ. તે તમને નહીં કહે કે તમારા બાળકોને શું ખવડાવવું. તે હજી પણ તમારો નિર્ણય છે, અને એમ જ રહેવું જોઈએ. તે બસ તમને સીધું કહેશે કે નિર્ણય પહેલાં પેકમાં ખરેખર શું છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product we rate is scored on ten yes-or-no checks, for every age group from {#} months to adults: children, boys and girls, men and women.', 'hi', 'हम जिस भी प्रोडक्ट को रेट करते हैं उसे दस हाँ-या-नहीं जाँच पर स्कोर किया जाता है, {#} महीने से वयस्कों तक हर उम्र समूह के लिए: बच्चे, लड़के और लड़कियाँ, पुरुष और महिलाएँ।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product we rate is scored on ten yes-or-no checks, for every age group from {#} months to adults: children, boys and girls, men and women.', 'bn', 'আমরা যে প্রোডাক্টই রেট করি তাকে দশটি হ্যাঁ-না পরীক্ষায় স্কোর করা হয়, {#} মাস থেকে প্রাপ্তবয়স্ক পর্যন্ত প্রতিটি বয়সের গ্রুপের জন্য: শিশু, ছেলে ও মেয়ে, পুরুষ ও মহিলা।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product we rate is scored on ten yes-or-no checks, for every age group from {#} months to adults: children, boys and girls, men and women.', 'gu', 'અમે જે પણ પ્રોડક્ટને રેટ કરીએ છીએ તેને દસ હા-કે-ના તપાસ પર સ્કોર કરવામાં આવે છે, {#} મહિનાથી પુખ્ત સુધી દરેક ઉંમર જૂથ માટે: બાળકો, છોકરા અને છોકરીઓ, પુરુષ અને સ્ત્રીઓ.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is a beta built with parents: where the numbers come from, what not yet checked means, and how to add a pack or report a mistake.', 'hi', 'Poshan Score अभिभावकों के साथ बना एक बीटा है: संख्याएँ कहाँ से आती हैं, "अभी जाँचा नहीं गया" का क्या मतलब है, और पैक कैसे जोड़ें या गलती कैसे बताएँ।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is a beta built with parents: where the numbers come from, what not yet checked means, and how to add a pack or report a mistake.', 'bn', 'Poshan Score অভিভাবকদের সঙ্গে তৈরি একটি বিটা: সংখ্যাগুলো কোথা থেকে আসে, "এখনও যাচাই হয়নি" মানে কী, আর কীভাবে প্যাক যোগ করবেন বা ভুল জানাবেন।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is a beta built with parents: where the numbers come from, what not yet checked means, and how to add a pack or report a mistake.', 'gu', 'Poshan Score વાલીઓ સાથે બનેલ એક બીટા છે: સંખ્યાઓ ક્યાંથી આવે છે, "હજી તપાસાયું નથી" નો અર્થ શું, અને પેક કેવી રીતે ઉમેરવો કે ભૂલ કેવી રીતે જણાવવી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<span_b>Poshan Score</span_b>', 'hi', '<span_b>Poshan Score</span_b>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
