INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('BETA', 'bn', 'বিটা', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('BETA', 'gu', 'બીટા', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every pack says it is healthy. We read the back. Poshan Score is a beta, and it gets better each time a parent adds a pack or corrects one.', 'hi', 'हर पैक कहता है कि वह सेहतमंद है। हम पीछे पढ़ते हैं। Poshan Score एक बीटा है, और हर बार जब कोई अभिभावक पैक जोड़ता या सुधारता है, यह बेहतर होता है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every pack says it is healthy. We read the back. Poshan Score is a beta, and it gets better each time a parent adds a pack or corrects one.', 'bn', 'প্রতিটি প্যাক বলে সে স্বাস্থ্যকর। আমরা পেছনটা পড়ি। Poshan Score একটি বিটা, আর যতবার কোনো অভিভাবক প্যাক যোগ করেন বা সংশোধন করেন, এটি আরও ভালো হয়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every pack says it is healthy. We read the back. Poshan Score is a beta, and it gets better each time a parent adds a pack or corrects one.', 'gu', 'દરેક પેક કહે છે કે તે હેલ્ધી છે. અમે પાછળ વાંચીએ છીએ. Poshan Score એક બીટા છે, અને જ્યારે પણ કોઈ વાલી પેક ઉમેરે કે સુધારે છે, તે વધુ સારો થાય છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Some scores come from open data that our team has not checked yet. Those are marked <b_a>not yet checked</b_a>. The numbers are the pack''s own label, but we can still have read or filed one wrongly.', 'hi', 'कुछ स्कोर खुले डेटा से आते हैं जिन्हें हमारी टीम ने अभी जाँचा नहीं है। उन पर <b_a>अभी जाँचा नहीं गया</b_a> लिखा होता है। संख्याएँ पैक के अपने लेबल की हैं, पर हमसे फिर भी किसी को गलत पढ़ना या दर्ज करना हो सकता है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Some scores come from open data that our team has not checked yet. Those are marked <b_a>not yet checked</b_a>. The numbers are the pack''s own label, but we can still have read or filed one wrongly.', 'bn', 'কিছু স্কোর খোলা ডেটা থেকে আসে যা আমাদের দল এখনও যাচাই করেনি। সেগুলোতে <b_a>এখনও যাচাই হয়নি</b_a> লেখা থাকে। সংখ্যাগুলো প্যাকের নিজস্ব লেবেলের, কিন্তু আমরা তবুও কোনোটা ভুল পড়ে বা ভুল জায়গায় রেখে থাকতে পারি।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Some scores come from open data that our team has not checked yet. Those are marked <b_a>not yet checked</b_a>. The numbers are the pack''s own label, but we can still have read or filed one wrongly.', 'gu', 'કેટલાક સ્કોર ખુલ્લા ડેટામાંથી આવે છે જે અમારી ટીમે હજી તપાસ્યા નથી. તેમના પર <b_a>હજી તપાસાયું નથી</b_a> લખેલું હોય છે. સંખ્યાઓ પેકના પોતાના લેબલની છે, પણ અમે હજી પણ કોઈને ખોટું વાંચ્યું કે નોંધ્યું હોઈ શકે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>The pack''s own label:</b_a> the nutrition table and the ingredient list, per {#} g, as printed.', 'hi', '<b_a>पैक का अपना लेबल:</b_a> पोषण तालिका और सामग्री की सूची, प्रति {#} ग्राम, जैसी छपी है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>The pack''s own label:</b_a> the nutrition table and the ingredient list, per {#} g, as printed.', 'bn', '<b_a>প্যাকের নিজস্ব লেবেল:</b_a> পুষ্টি তালিকা ও উপকরণের তালিকা, প্রতি {#} গ্রামে, যেমন ছাপা আছে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>The pack''s own label:</b_a> the nutrition table and the ingredient list, per {#} g, as printed.', 'gu', '<b_a>પેકનું પોતાનું લેબલ:</b_a> પોષણ કોષ્ટક અને સામગ્રીની યાદી, પ્રતિ {#} ગ્રામ, જેવી છાપેલી છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Open Food Facts</b_a>, a free database of food products made by people around the world (<a_b>openfoodfacts.org</a_b>, Open Database Licence). We credit it on every page that uses it.', 'hi', '<b_a>Open Food Facts</b_a>, दुनिया भर के लोगों द्वारा बनाया गया खाद्य उत्पादों का एक मुफ़्त डेटाबेस (<a_b>openfoodfacts.org</a_b>, Open Database Licence)। हम इसे हर उस पेज पर श्रेय देते हैं जो इसका इस्तेमाल करता है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Open Food Facts</b_a>, a free database of food products made by people around the world (<a_b>openfoodfacts.org</a_b>, Open Database Licence). We credit it on every page that uses it.', 'bn', '<b_a>Open Food Facts</b_a>, বিশ্বজুড়ে মানুষের তৈরি খাদ্য পণ্যের একটি বিনামূল্যের ডেটাবেস (<a_b>openfoodfacts.org</a_b>, Open Database Licence)। যে পেজেই এটি ব্যবহার হয় সেখানে আমরা এর কৃতিত্ব দিই।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Open Food Facts</b_a>, a free database of food products made by people around the world (<a_b>openfoodfacts.org</a_b>, Open Database Licence). We credit it on every page that uses it.', 'gu', '<b_a>Open Food Facts</b_a>, દુનિયાભરના લોકોએ બનાવેલો ખાદ્ય ઉત્પાદનોનો એક મફત ડેટાબેઝ (<a_b>openfoodfacts.org</a_b>, Open Database Licence). જે પેજ તેનો ઉપયોગ કરે છે ત્યાં અમે તેને શ્રેય આપીએ છીએ.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Photos from parents:</b_a> the front and back of a pack. Our label reader reads the table, and our team checks the numbers against the photo before a pack is marked checked.', 'hi', '<b_a>अभिभावकों की फ़ोटो:</b_a> पैक का आगे और पीछे का हिस्सा। हमारा लेबल रीडर तालिका पढ़ता है, और पैक को जाँचा हुआ चिह्नित करने से पहले हमारी टीम संख्याओं को फ़ोटो से मिलाती है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Photos from parents:</b_a> the front and back of a pack. Our label reader reads the table, and our team checks the numbers against the photo before a pack is marked checked.', 'bn', '<b_a>অভিভাবকদের ছবি:</b_a> প্যাকের সামনে ও পেছন। আমাদের লেবেল রিডার তালিকা পড়ে, আর প্যাক যাচাই হয়েছে বলে চিহ্নিত করার আগে আমাদের দল সংখ্যাগুলো ছবির সঙ্গে মেলায়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Photos from parents:</b_a> the front and back of a pack. Our label reader reads the table, and our team checks the numbers against the photo before a pack is marked checked.', 'gu', '<b_a>વાલીઓના ફોટા:</b_a> પેકનો આગળ અને પાછળનો ભાગ. અમારું લેબલ રીડર કોષ્ટક વાંચે છે, અને પેકને તપાસેલો ચિહ્નિત કરતાં પહેલાં અમારી ટીમ સંખ્યાઓને ફોટા સાથે મેળવે છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('No brand pays to be here, and no brand can pay to change a score. How a score is worked out is open for anyone to read on the <a_a>Age & Metrics</a_a> page.', 'hi', 'कोई ब्रांड यहाँ आने के लिए भुगतान नहीं करता, और कोई ब्रांड स्कोर बदलने के लिए भुगतान नहीं कर सकता। स्कोर कैसे निकलता है, यह <a_a>उम्र और मापदंड</a_a> पेज पर हर किसी के पढ़ने के लिए खुला है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('No brand pays to be here, and no brand can pay to change a score. How a score is worked out is open for anyone to read on the <a_a>Age & Metrics</a_a> page.', 'bn', 'কোনো ব্র্যান্ড এখানে থাকার জন্য টাকা দেয় না, আর কোনো ব্র্যান্ড স্কোর বদলাতে টাকা দিতে পারে না। স্কোর কীভাবে হিসাব হয় তা <a_a>বয়স ও মাপকাঠি</a_a> পেজে যে কেউ পড়তে পারেন।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('No brand pays to be here, and no brand can pay to change a score. How a score is worked out is open for anyone to read on the <a_a>Age & Metrics</a_a> page.', 'gu', 'કોઈ બ્રાન્ડ અહીં આવવા ચૂકવણી કરતી નથી, અને કોઈ બ્રાન્ડ સ્કોર બદલવા ચૂકવણી કરી શકતી નથી. સ્કોર કેવી રીતે કઢાય છે તે <a_a>ઉંમર અને માપદંડ</a_a> પેજ પર કોઈ પણ વાંચી શકે છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Is this your pack?</b_a> On a pack that is not yet checked, tell us if the name on your pack is different. Then photograph yours, and it is scored from your photos.', 'hi', '<b_a>क्या यह आपका पैक है?</b_a> जिस पैक को अभी जाँचा नहीं गया, उस पर अगर आपके पैक का नाम अलग है तो हमें बताएँ। फिर अपने पैक की फ़ोटो लें, और वह आपकी फ़ोटो से स्कोर होगा।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Is this your pack?</b_a> On a pack that is not yet checked, tell us if the name on your pack is different. Then photograph yours, and it is scored from your photos.', 'bn', '<b_a>এটা কি আপনার প্যাক?</b_a> যে প্যাক এখনও যাচাই হয়নি, তাতে আপনার প্যাকের নাম আলাদা হলে আমাদের জানান। তারপর আপনার প্যাকের ছবি তুলুন, আপনার ছবি থেকে স্কোর হবে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Is this your pack?</b_a> On a pack that is not yet checked, tell us if the name on your pack is different. Then photograph yours, and it is scored from your photos.', 'gu', '<b_a>શું આ તમારો પેક છે?</b_a> જે પેક હજી તપાસાયો નથી, તેના પર તમારા પેકનું નામ અલગ હોય તો અમને જણાવો. પછી તમારા પેકનો ફોટો લો, અને તે તમારા ફોટા પરથી સ્કોર થશે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Report a mistake</b_a> on any pack: a wrong name, numbers that do not match the label, or a wrong photo.', 'hi', 'किसी भी पैक पर <b_a>गलती बताएँ</b_a>: गलत नाम, लेबल से न मिलने वाली संख्याएँ, या गलत फ़ोटो।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Report a mistake</b_a> on any pack: a wrong name, numbers that do not match the label, or a wrong photo.', 'bn', 'যেকোনো প্যাকে <b_a>ভুল জানান</b_a>: ভুল নাম, লেবেলের সঙ্গে না মেলা সংখ্যা, বা ভুল ছবি।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Report a mistake</b_a> on any pack: a wrong name, numbers that do not match the label, or a wrong photo.', 'gu', 'કોઈ પણ પેક પર <b_a>ભૂલ જણાવો</b_a>: ખોટું નામ, લેબલ સાથે ન મળતી સંખ્યાઓ, અથવા ખોટો ફોટો.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('When you send photos you tick a box to say they are of a pack you have and that KidPoshan may show them and use them to score the pack. Please photograph only the pack, not people.', 'hi', 'जब आप फ़ोटो भेजते हैं तो आप एक बॉक्स टिक करके कहते हैं कि वे आपके पास मौजूद पैक की हैं और KidPoshan उन्हें दिखा सकता है और पैक को स्कोर करने में इस्तेमाल कर सकता है। कृपया सिर्फ़ पैक की फ़ोटो लें, लोगों की नहीं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('When you send photos you tick a box to say they are of a pack you have and that KidPoshan may show them and use them to score the pack. Please photograph only the pack, not people.', 'bn', 'আপনি যখন ছবি পাঠান তখন একটি বাক্সে টিক দিয়ে জানান যে সেগুলো আপনার কাছে থাকা প্যাকের আর KidPoshan সেগুলো দেখাতে এবং প্যাক স্কোর করতে ব্যবহার করতে পারে। অনুগ্রহ করে শুধু প্যাকের ছবি তুলুন, মানুষের নয়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('When you send photos you tick a box to say they are of a pack you have and that KidPoshan may show them and use them to score the pack. Please photograph only the pack, not people.', 'gu', 'જ્યારે તમે ફોટા મોકલો છો ત્યારે એક બૉક્સ ટિક કરીને કહો છો કે તે તમારી પાસેના પેકના છે અને KidPoshan તેમને બતાવી શકે છે અને પેકને સ્કોર કરવામાં વાપરી શકે છે. કૃપા કરીને ફક્ત પેકનો ફોટો લો, લોકોનો નહીં.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Your email is optional. If you leave it, we use it once, to thank you when your pack is checked, or to tell you what we did about a report. We use it for nothing else, and we do not share it.', 'hi', 'आपका ईमेल वैकल्पिक है। अगर आप देते हैं, तो हम उसे एक बार इस्तेमाल करते हैं: आपका पैक जाँचे जाने पर धन्यवाद देने के लिए, या किसी रिपोर्ट पर हमने क्या किया यह बताने के लिए। हम उसे किसी और चीज़ के लिए इस्तेमाल नहीं करते, और साझा नहीं करते।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Your email is optional. If you leave it, we use it once, to thank you when your pack is checked, or to tell you what we did about a report. We use it for nothing else, and we do not share it.', 'bn', 'আপনার ইমেইল ঐচ্ছিক। দিলে আমরা একবার ব্যবহার করি: আপনার প্যাক যাচাই হলে ধন্যবাদ জানাতে, বা কোনো রিপোর্টে আমরা কী করেছি তা জানাতে। আমরা এটি অন্য কিছুর জন্য ব্যবহার করি না, আর শেয়ার করি না।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Your email is optional. If you leave it, we use it once, to thank you when your pack is checked, or to tell you what we did about a report. We use it for nothing else, and we do not share it.', 'gu', 'તમારો ઈમેલ વૈકલ્પિક છે. જો તમે આપો, તો અમે તેને એક વાર વાપરીએ છીએ: તમારો પેક તપાસાય ત્યારે આભાર માનવા, અથવા કોઈ રિપોર્ટ પર અમે શું કર્યું તે જણાવવા. અમે તેને બીજા કશા માટે વાપરતા નથી, અને વહેંચતા નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We keep no name or phone number with a scan or a report. More is on the <a_a>privacy page</a_a>.', 'hi', 'हम किसी स्कैन या रिपोर्ट के साथ कोई नाम या फ़ोन नंबर नहीं रखते। ज़्यादा जानकारी <a_a>गोपनीयता पेज</a_a> पर है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We keep no name or phone number with a scan or a report. More is on the <a_a>privacy page</a_a>.', 'bn', 'আমরা কোনো স্ক্যান বা রিপোর্টের সঙ্গে কোনো নাম বা ফোন নম্বর রাখি না। আরও তথ্য <a_a>গোপনীয়তা পেজে</a_a> আছে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We keep no name or phone number with a scan or a report. More is on the <a_a>privacy page</a_a>.', 'gu', 'અમે કોઈ સ્કેન કે રિપોર્ટ સાથે કોઈ નામ કે ફોન નંબર રાખતા નથી. વધુ માહિતી <a_a>ગોપનીયતા પેજ</a_a> પર છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Something we should know, or want to take part? <a_a>kidposhan@gmail.com</a_a>', 'hi', 'कुछ ऐसा जो हमें जानना चाहिए, या शामिल होना चाहते हैं? <a_a>kidposhan@gmail.com</a_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Something we should know, or want to take part? <a_a>kidposhan@gmail.com</a_a>', 'bn', 'এমন কিছু যা আমাদের জানা উচিত, বা অংশ নিতে চান? <a_a>kidposhan@gmail.com</a_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Something we should know, or want to take part? <a_a>kidposhan@gmail.com</a_a>', 'gu', 'કંઈક જે અમને જાણવું જોઈએ, અથવા ભાગ લેવા માંગો છો? <a_a>kidposhan@gmail.com</a_a>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is an independent rating, not a certification. The age guide is general and cautious. It is not medical advice.', 'hi', 'Poshan Score एक स्वतंत्र रेटिंग है, कोई प्रमाणन नहीं। उम्र की जानकारी सामान्य और सावधानी वाली है। यह चिकित्सकीय सलाह नहीं है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is an independent rating, not a certification. The age guide is general and cautious. It is not medical advice.', 'bn', 'Poshan Score একটি স্বাধীন রেটিং, কোনো সার্টিফিকেশন নয়। বয়স অনুযায়ী নির্দেশিকা সাধারণ ও সতর্ক। এটি চিকিৎসা পরামর্শ নয়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is an independent rating, not a certification. The age guide is general and cautious. It is not medical advice.', 'gu', 'Poshan Score એક સ્વતંત્ર રેટિંગ છે, પ્રમાણપત્ર નથી. ઉંમર મુજબની માહિતી સામાન્ય અને સાવચેતીભરી છે. તે તબીબી સલાહ નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan · <a_a>www.kidposhan.in</a_a> · Last updated {#} October {#}', 'hi', 'KidPoshan · <a_a>www.kidposhan.in</a_a> · अंतिम अपडेट {#} अक्टूबर {#}', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan · <a_a>www.kidposhan.in</a_a> · Last updated {#} October {#}', 'bn', 'KidPoshan · <a_a>www.kidposhan.in</a_a> · সর্বশেষ আপডেট {#} অক্টোবর {#}', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan · <a_a>www.kidposhan.in</a_a> · Last updated {#} October {#}', 'gu', 'KidPoshan · <a_a>www.kidposhan.in</a_a> · છેલ્લે અપડેટ {#} ઑક્ટોબર {#}', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan helps parents decide what to cook for their children by age, meal and season, and gives every recipe a Poshan Score. This page says what we collect, why, who sees it, and how to have it removed. For anything here, write to <a_a>kidposhan@gmail.com</a_a>.', 'hi', 'KidPoshan अभिभावकों को यह तय करने में मदद करता है कि बच्चों के लिए उम्र, भोजन और मौसम के हिसाब से क्या पकाएँ, और हर रेसिपी को एक Poshan Score देता है। यह पेज बताता है कि हम क्या इकट्ठा करते हैं, क्यों, कौन इसे देखता है, और इसे कैसे हटवाया जाए। यहाँ की किसी भी बात के लिए <a_a>kidposhan@gmail.com</a_a> पर लिखें।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan helps parents decide what to cook for their children by age, meal and season, and gives every recipe a Poshan Score. This page says what we collect, why, who sees it, and how to have it removed. For anything here, write to <a_a>kidposhan@gmail.com</a_a>.', 'bn', 'KidPoshan অভিভাবকদের সন্তানদের জন্য বয়স, বেলা ও ঋতু অনুযায়ী কী রান্না করবেন তা ঠিক করতে সাহায্য করে, আর প্রতিটি রেসিপিকে একটি Poshan Score দেয়। এই পেজ বলে আমরা কী সংগ্রহ করি, কেন, কে এটি দেখে, আর কীভাবে তা সরানো যায়। এখানকার যেকোনো বিষয়ে <a_a>kidposhan@gmail.com</a_a>-এ লিখুন।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan helps parents decide what to cook for their children by age, meal and season, and gives every recipe a Poshan Score. This page says what we collect, why, who sees it, and how to have it removed. For anything here, write to <a_a>kidposhan@gmail.com</a_a>.', 'gu', 'KidPoshan વાલીઓને બાળકો માટે ઉંમર, ભોજન અને ઋતુ મુજબ શું રાંધવું તે નક્કી કરવામાં મદદ કરે છે, અને દરેક રેસીપીને એક Poshan Score આપે છે. આ પેજ જણાવે છે કે અમે શું એકત્ર કરીએ છીએ, શા માટે, કોણ તેને જુએ છે, અને તેને કેવી રીતે દૂર કરાવવું. અહીંની કોઈ પણ બાબત માટે <a_a>kidposhan@gmail.com</a_a> પર લખો.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Name, mobile number and email address</b_a>, only if you give them (when you rate a recipe, send a remark, or fill in the small "Join KidPoshan" box on a recipe page). We use them to know who rated a recipe or wrote a remark. We do not check that a number or address is yours. Your mobile number and email are <b_b>never shown</b_b> on the site. Your name is shown only next to a remark that our team has approved.', 'hi', '<b_a>नाम, मोबाइल नंबर और ईमेल पता</b_a>, सिर्फ़ अगर आप देते हैं (जब आप किसी रेसिपी को रेट करते हैं, टिप्पणी भेजते हैं, या रेसिपी पेज पर छोटा "KidPoshan से जुड़ें" बॉक्स भरते हैं)। हम इनका इस्तेमाल यह जानने के लिए करते हैं कि किसने रेसिपी रेट की या टिप्पणी लिखी। हम यह नहीं जाँचते कि नंबर या पता आपका है। आपका मोबाइल नंबर और ईमेल साइट पर <b_b>कभी नहीं दिखाए जाते</b_b>। आपका नाम सिर्फ़ उस टिप्पणी के साथ दिखता है जिसे हमारी टीम ने मंज़ूर किया है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Name, mobile number and email address</b_a>, only if you give them (when you rate a recipe, send a remark, or fill in the small "Join KidPoshan" box on a recipe page). We use them to know who rated a recipe or wrote a remark. We do not check that a number or address is yours. Your mobile number and email are <b_b>never shown</b_b> on the site. Your name is shown only next to a remark that our team has approved.', 'bn', '<b_a>নাম, মোবাইল নম্বর ও ইমেইল ঠিকানা</b_a>, শুধু যদি আপনি দেন (যখন কোনো রেসিপি রেট করেন, মন্তব্য পাঠান, বা রেসিপি পেজে ছোট "KidPoshan-এ যোগ দিন" বাক্স পূরণ করেন)। আমরা এগুলো ব্যবহার করি জানতে কে রেসিপি রেট করেছেন বা মন্তব্য লিখেছেন। আমরা যাচাই করি না যে নম্বর বা ঠিকানা আপনার। আপনার মোবাইল নম্বর ও ইমেইল সাইটে <b_b>কখনও দেখানো হয় না</b_b>। আপনার নাম শুধু সেই মন্তব্যের পাশে দেখা যায় যা আমাদের দল অনুমোদন করেছে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Name, mobile number and email address</b_a>, only if you give them (when you rate a recipe, send a remark, or fill in the small "Join KidPoshan" box on a recipe page). We use them to know who rated a recipe or wrote a remark. We do not check that a number or address is yours. Your mobile number and email are <b_b>never shown</b_b> on the site. Your name is shown only next to a remark that our team has approved.', 'gu', '<b_a>નામ, મોબાઇલ નંબર અને ઈમેલ સરનામું</b_a>, ફક્ત જો તમે આપો તો (જ્યારે તમે કોઈ રેસીપીને રેટ કરો, ટિપ્પણી મોકલો, અથવા રેસીપી પેજ પર નાનું "KidPoshan સાથે જોડાઓ" બૉક્સ ભરો). અમે તેનો ઉપયોગ જાણવા માટે કરીએ છીએ કે કોણે રેસીપી રેટ કરી કે ટિપ્પણી લખી. અમે તપાસતા નથી કે નંબર કે સરનામું તમારું છે. તમારો મોબાઇલ નંબર અને ઈમેલ સાઇટ પર <b_b>ક્યારેય બતાવાતા નથી</b_b>. તમારું નામ ફક્ત તે ટિપ્પણી સાથે દેખાય છે જેને અમારી ટીમે મંજૂર કરી છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Ratings and remarks</b_a> you submit. A remark appears on the site only after our team approves it, and you can ask us to remove it.', 'hi', 'आपकी भेजी <b_a>रेटिंग और टिप्पणियाँ</b_a>। कोई टिप्पणी साइट पर तभी दिखती है जब हमारी टीम उसे मंज़ूर करे, और आप उसे हटवाने के लिए कह सकते हैं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Ratings and remarks</b_a> you submit. A remark appears on the site only after our team approves it, and you can ask us to remove it.', 'bn', 'আপনার পাঠানো <b_a>রেটিং ও মন্তব্য</b_a>। কোনো মন্তব্য সাইটে তখনই দেখা যায় যখন আমাদের দল তা অনুমোদন করে, আর আপনি তা সরাতে বলতে পারেন।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Ratings and remarks</b_a> you submit. A remark appears on the site only after our team approves it, and you can ask us to remove it.', 'gu', 'તમે મોકલેલ <b_a>રેટિંગ અને ટિપ્પણીઓ</b_a>. કોઈ ટિપ્પણી સાઇટ પર ત્યારે જ દેખાય છે જ્યારે અમારી ટીમ તેને મંજૂર કરે, અને તમે તેને દૂર કરવા કહી શકો છો.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Optional ₹{#} support.</b_a> You pay in your own UPI app; we never see your bank or card details. If you tell us you have paid, we keep the amount, the time and the payment reference you typed, so we can confirm it.', 'hi', '<b_a>वैकल्पिक ₹{#} सहयोग।</b_a> आप अपने UPI ऐप में भुगतान करते हैं; हम आपका बैंक या कार्ड विवरण कभी नहीं देखते। अगर आप बताते हैं कि आपने भुगतान किया है, तो हम राशि, समय और आपके लिखे भुगतान संदर्भ को रखते हैं, ताकि उसकी पुष्टि कर सकें।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Optional ₹{#} support.</b_a> You pay in your own UPI app; we never see your bank or card details. If you tell us you have paid, we keep the amount, the time and the payment reference you typed, so we can confirm it.', 'bn', '<b_a>ঐচ্ছিক ₹{#} সহায়তা।</b_a> আপনি আপনার নিজের UPI অ্যাপে টাকা দেন; আমরা আপনার ব্যাংক বা কার্ডের তথ্য কখনও দেখি না। আপনি টাকা দিয়েছেন জানালে আমরা পরিমাণ, সময় ও আপনার লেখা পেমেন্ট রেফারেন্স রাখি, যাতে তা নিশ্চিত করতে পারি।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Optional ₹{#} support.</b_a> You pay in your own UPI app; we never see your bank or card details. If you tell us you have paid, we keep the amount, the time and the payment reference you typed, so we can confirm it.', 'gu', '<b_a>વૈકલ્પિક ₹{#} સહયોગ.</b_a> તમે તમારી પોતાની UPI ઍપમાં ચૂકવણી કરો છો; અમે તમારી બેંક કે કાર્ડની વિગતો ક્યારેય જોતા નથી. જો તમે જણાવો કે તમે ચૂકવણી કરી છે, તો અમે રકમ, સમય અને તમે લખેલો ચુકવણી સંદર્ભ રાખીએ છીએ, જેથી તેની પુષ્ટિ કરી શકીએ.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>A random id kept in your browser</b_a> (no name, number or IP address is stored with it). It lets us count how many different browsers visit and show you recipes you have not seen yet when you repeat a search. Your browser also keeps your chosen filters, shopping ticks and login token on your device. We do not use advertising or tracking cookies.', 'hi', '<b_a>आपके ब्राउज़र में रखा एक यादृच्छिक आईडी</b_a> (उसके साथ कोई नाम, नंबर या IP पता नहीं रखा जाता)। यह हमें गिनने देता है कि कितने अलग ब्राउज़र आते हैं और जब आप कोई खोज दोहराते हैं तो आपको वे रेसिपी दिखाने देता है जो आपने अभी नहीं देखीं। आपका ब्राउज़र आपकी चुनी फ़िल्टर, खरीदारी की टिक और लॉगिन टोकन भी आपके डिवाइस पर रखता है। हम विज्ञापन या ट्रैकिंग कुकीज़ का इस्तेमाल नहीं करते।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>A random id kept in your browser</b_a> (no name, number or IP address is stored with it). It lets us count how many different browsers visit and show you recipes you have not seen yet when you repeat a search. Your browser also keeps your chosen filters, shopping ticks and login token on your device. We do not use advertising or tracking cookies.', 'bn', '<b_a>আপনার ব্রাউজারে রাখা একটি এলোমেলো আইডি</b_a> (এর সঙ্গে কোনো নাম, নম্বর বা IP ঠিকানা রাখা হয় না)। এটি আমাদের গুনতে দেয় কতগুলো আলাদা ব্রাউজার আসে আর যখন আপনি কোনো খোঁজ আবার করেন তখন আপনাকে সেই রেসিপি দেখাতে দেয় যা আপনি এখনও দেখেননি। আপনার ব্রাউজার আপনার বেছে নেওয়া ফিল্টার, কেনাকাটার টিক ও লগইন টোকেনও আপনার ডিভাইসে রাখে। আমরা বিজ্ঞাপন বা ট্র্যাকিং কুকি ব্যবহার করি না।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>A random id kept in your browser</b_a> (no name, number or IP address is stored with it). It lets us count how many different browsers visit and show you recipes you have not seen yet when you repeat a search. Your browser also keeps your chosen filters, shopping ticks and login token on your device. We do not use advertising or tracking cookies.', 'gu', '<b_a>તમારા બ્રાઉઝરમાં રાખેલ એક રેન્ડમ આઈડી</b_a> (તેની સાથે કોઈ નામ, નંબર કે IP સરનામું રાખવામાં આવતું નથી). તે અમને ગણવા દે છે કે કેટલા અલગ બ્રાઉઝર આવે છે અને જ્યારે તમે કોઈ શોધ ફરી કરો ત્યારે તમને તે રેસીપી બતાવવા દે છે જે તમે હજી જોઈ નથી. તમારું બ્રાઉઝર તમારા પસંદ કરેલા ફિલ્ટર, ખરીદીની ટિક અને લૉગિન ટોકન પણ તમારા ડિવાઇસ પર રાખે છે. અમે જાહેરાત કે ટ્રૅકિંગ કુકીઝ વાપરતા નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Which pages are opened and for how long.</b_a> For each page view we keep the page, the time, how long it stayed on screen, and the country and city your connection appears to be in. We do not keep your IP address. This is only for our own anonymous visit statistics; crawlers and monitors are not counted as visitors, and these records are deleted after about {#} months.', 'hi', '<b_a>कौन-से पेज खुले और कितनी देर के लिए।</b_a> हर पेज व्यू के लिए हम पेज, समय, वह कितनी देर स्क्रीन पर रहा, और आपका कनेक्शन किस देश और शहर का लगता है, रखते हैं। हम आपका IP पता नहीं रखते। यह सिर्फ़ हमारे अपने गुमनाम विज़िट आँकड़ों के लिए है; क्रॉलर और मॉनिटर को विज़िटर नहीं गिना जाता, और ये रिकॉर्ड लगभग {#} महीने बाद मिटा दिए जाते हैं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Which pages are opened and for how long.</b_a> For each page view we keep the page, the time, how long it stayed on screen, and the country and city your connection appears to be in. We do not keep your IP address. This is only for our own anonymous visit statistics; crawlers and monitors are not counted as visitors, and these records are deleted after about {#} months.', 'bn', '<b_a>কোন পেজ খোলা হল আর কতক্ষণের জন্য।</b_a> প্রতিটি পেজ ভিউয়ের জন্য আমরা পেজ, সময়, কতক্ষণ স্ক্রিনে ছিল, আর আপনার সংযোগ কোন দেশ ও শহরের মনে হয় তা রাখি। আমরা আপনার IP ঠিকানা রাখি না। এটি শুধু আমাদের নিজস্ব বেনামি ভিজিট পরিসংখ্যানের জন্য; ক্রলার ও মনিটরকে ভিজিটর গণ্য করা হয় না, আর এই রেকর্ডগুলো প্রায় {#} মাস পরে মুছে ফেলা হয়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Which pages are opened and for how long.</b_a> For each page view we keep the page, the time, how long it stayed on screen, and the country and city your connection appears to be in. We do not keep your IP address. This is only for our own anonymous visit statistics; crawlers and monitors are not counted as visitors, and these records are deleted after about {#} months.', 'gu', '<b_a>કયા પેજ ખુલ્યા અને કેટલી વાર માટે.</b_a> દરેક પેજ વ્યૂ માટે અમે પેજ, સમય, તે કેટલી વાર સ્ક્રીન પર રહ્યું, અને તમારું કનેક્શન કયા દેશ અને શહેરનું લાગે છે તે રાખીએ છીએ. અમે તમારું IP સરનામું રાખતા નથી. આ ફક્ત અમારા પોતાના અનામી વિઝિટ આંકડા માટે છે; ક્રૉલર અને મૉનિટરને વિઝિટર ગણવામાં આવતા નથી, અને આ રેકોર્ડ લગભગ {#} મહિના પછી ભૂંસી નાખવામાં આવે છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Packs you scan.</b_a> When you scan a barcode we look the pack up. If you send photos of a pack, we keep the barcode and the two photos, and read the nutrition label from the back photo. The photos may be shown with the pack on the Products page after our team has checked it, so please photograph only the pack and not people. We keep no name, number or address with a scan. To stop one phone sending too many, we keep a one-day code made from your connection (not your IP address) for two days.', 'hi', '<b_a>जो पैक आप स्कैन करते हैं।</b_a> जब आप बारकोड स्कैन करते हैं तो हम पैक को खोजते हैं। अगर आप किसी पैक की फ़ोटो भेजते हैं, तो हम बारकोड और दोनों फ़ोटो रखते हैं, और पीछे की फ़ोटो से पोषण लेबल पढ़ते हैं। हमारी टीम के जाँचने के बाद फ़ोटो पैक के साथ प्रोडक्ट पेज पर दिखाई जा सकती हैं, इसलिए कृपया सिर्फ़ पैक की फ़ोटो लें, लोगों की नहीं। हम किसी स्कैन के साथ कोई नाम, नंबर या पता नहीं रखते। एक फ़ोन को बहुत ज़्यादा भेजने से रोकने के लिए, हम आपके कनेक्शन से बना (आपके IP पते से नहीं) एक दिन का कोड दो दिन तक रखते हैं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Packs you scan.</b_a> When you scan a barcode we look the pack up. If you send photos of a pack, we keep the barcode and the two photos, and read the nutrition label from the back photo. The photos may be shown with the pack on the Products page after our team has checked it, so please photograph only the pack and not people. We keep no name, number or address with a scan. To stop one phone sending too many, we keep a one-day code made from your connection (not your IP address) for two days.', 'bn', '<b_a>আপনি যে প্যাক স্ক্যান করেন।</b_a> আপনি বারকোড স্ক্যান করলে আমরা প্যাকটি খুঁজি। আপনি কোনো প্যাকের ছবি পাঠালে আমরা বারকোড ও দুটি ছবি রাখি, আর পেছনের ছবি থেকে পুষ্টি লেবেল পড়ি। আমাদের দল যাচাই করার পর ছবিগুলো প্যাকের সঙ্গে প্রোডাক্ট পেজে দেখানো হতে পারে, তাই অনুগ্রহ করে শুধু প্যাকের ছবি তুলুন, মানুষের নয়। আমরা কোনো স্ক্যানের সঙ্গে কোনো নাম, নম্বর বা ঠিকানা রাখি না। একটি ফোন থেকে অতিরিক্ত পাঠানো ঠেকাতে আমরা আপনার সংযোগ থেকে তৈরি (আপনার IP ঠিকানা থেকে নয়) একদিনের কোড দুদিন রাখি।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Packs you scan.</b_a> When you scan a barcode we look the pack up. If you send photos of a pack, we keep the barcode and the two photos, and read the nutrition label from the back photo. The photos may be shown with the pack on the Products page after our team has checked it, so please photograph only the pack and not people. We keep no name, number or address with a scan. To stop one phone sending too many, we keep a one-day code made from your connection (not your IP address) for two days.', 'gu', '<b_a>તમે સ્કેન કરેલા પેક.</b_a> જ્યારે તમે બારકોડ સ્કેન કરો છો ત્યારે અમે પેક શોધીએ છીએ. જો તમે કોઈ પેકના ફોટા મોકલો, તો અમે બારકોડ અને બંને ફોટા રાખીએ છીએ, અને પાછળના ફોટા પરથી પોષણ લેબલ વાંચીએ છીએ. અમારી ટીમ તપાસે પછી ફોટા પેક સાથે પ્રોડક્ટ પેજ પર બતાવાઈ શકે છે, તેથી કૃપા કરીને ફક્ત પેકનો ફોટો લો, લોકોનો નહીં. અમે કોઈ સ્કેન સાથે કોઈ નામ, નંબર કે સરનામું રાખતા નથી. એક ફોનથી વધુ પડતું મોકલવાનું રોકવા, અમે તમારા કનેક્શનમાંથી બનેલો (તમારા IP સરનામામાંથી નહીં) એક દિવસનો કોડ બે દિવસ રાખીએ છીએ.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Mistake reports and your optional email.</b_a> If you report a mistake on a pack, we keep what you wrote and the pack it is about. If you leave an email (with a report or with photos), we use it once, to thank you when the pack is checked or to tell you what we did, and for nothing else. Leaving it is always optional. When you send photos you tick a box to say they are of a pack you have and that KidPoshan may show them and use them to score the pack.', 'hi', '<b_a>गलती की रिपोर्ट और आपका वैकल्पिक ईमेल।</b_a> अगर आप किसी पैक पर गलती की रिपोर्ट करते हैं, तो हम जो आपने लिखा और जिस पैक के बारे में है, उसे रखते हैं। अगर आप ईमेल छोड़ते हैं (रिपोर्ट या फ़ोटो के साथ), तो हम उसे एक बार इस्तेमाल करते हैं: पैक जाँचे जाने पर धन्यवाद देने या यह बताने के लिए कि हमने क्या किया, और किसी और चीज़ के लिए नहीं। इसे छोड़ना हमेशा वैकल्पिक है। जब आप फ़ोटो भेजते हैं तो आप एक बॉक्स टिक करके कहते हैं कि वे आपके पास मौजूद पैक की हैं और KidPoshan उन्हें दिखा सकता है और पैक को स्कोर करने में इस्तेमाल कर सकता है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Mistake reports and your optional email.</b_a> If you report a mistake on a pack, we keep what you wrote and the pack it is about. If you leave an email (with a report or with photos), we use it once, to thank you when the pack is checked or to tell you what we did, and for nothing else. Leaving it is always optional. When you send photos you tick a box to say they are of a pack you have and that KidPoshan may show them and use them to score the pack.', 'bn', '<b_a>ভুলের রিপোর্ট ও আপনার ঐচ্ছিক ইমেইল।</b_a> আপনি কোনো প্যাকে ভুলের রিপোর্ট করলে আমরা আপনার লেখা ও যে প্যাক সম্পর্কে তা রাখি। আপনি ইমেইল দিলে (রিপোর্ট বা ছবির সঙ্গে) আমরা একবার ব্যবহার করি: প্যাক যাচাই হলে ধন্যবাদ জানাতে বা আমরা কী করেছি তা জানাতে, আর অন্য কিছুর জন্য নয়। এটি দেওয়া সবসময় ঐচ্ছিক। আপনি ছবি পাঠালে একটি বাক্সে টিক দিয়ে জানান যে সেগুলো আপনার কাছে থাকা প্যাকের আর KidPoshan সেগুলো দেখাতে এবং প্যাক স্কোর করতে ব্যবহার করতে পারে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Mistake reports and your optional email.</b_a> If you report a mistake on a pack, we keep what you wrote and the pack it is about. If you leave an email (with a report or with photos), we use it once, to thank you when the pack is checked or to tell you what we did, and for nothing else. Leaving it is always optional. When you send photos you tick a box to say they are of a pack you have and that KidPoshan may show them and use them to score the pack.', 'gu', '<b_a>ભૂલના રિપોર્ટ અને તમારો વૈકલ્પિક ઈમેલ.</b_a> જો તમે કોઈ પેક પર ભૂલનો રિપોર્ટ કરો, તો અમે તમે જે લખ્યું અને જે પેક વિશે છે તે રાખીએ છીએ. જો તમે ઈમેલ છોડો (રિપોર્ટ કે ફોટા સાથે), તો અમે તેને એક વાર વાપરીએ છીએ: પેક તપાસાય ત્યારે આભાર માનવા અથવા અમે શું કર્યું તે જણાવવા, અને બીજા કશા માટે નહીં. તે છોડવું હંમેશા વૈકલ્પિક છે. જ્યારે તમે ફોટા મોકલો છો ત્યારે તમે એક બૉક્સ ટિક કરીને કહો છો કે તે તમારી પાસેના પેકના છે અને KidPoshan તેમને બતાવી શકે છે અને પેકને સ્કોર કરવામાં વાપરી શકે છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Saved recipes and your weekly plan</b_a> stay on your phone. Only if you choose to use them on another device do we ask for your mobile number and a one-time code sent by SMS; the saved list is then stored under that verified number so nobody else can open it.', 'hi', '<b_a>सेव की गई रेसिपी और आपकी हफ़्ते की योजना</b_a> आपके फ़ोन पर रहती हैं। सिर्फ़ अगर आप उन्हें दूसरे डिवाइस पर इस्तेमाल करना चुनें, तो हम आपका मोबाइल नंबर और SMS से भेजा एक बार का कोड माँगते हैं; सेव की गई सूची फिर उस सत्यापित नंबर के तहत रखी जाती है ताकि कोई और उसे न खोल सके।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Saved recipes and your weekly plan</b_a> stay on your phone. Only if you choose to use them on another device do we ask for your mobile number and a one-time code sent by SMS; the saved list is then stored under that verified number so nobody else can open it.', 'bn', '<b_a>সেভ করা রেসিপি ও আপনার সাপ্তাহিক পরিকল্পনা</b_a> আপনার ফোনেই থাকে। শুধু যদি আপনি সেগুলো অন্য ডিভাইসে ব্যবহার করতে চান, তবেই আমরা আপনার মোবাইল নম্বর ও SMS-এ পাঠানো একবারের কোড চাই; সেভ করা তালিকা তখন সেই যাচাই করা নম্বরের অধীনে রাখা হয় যাতে অন্য কেউ তা খুলতে না পারে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('<b_a>Saved recipes and your weekly plan</b_a> stay on your phone. Only if you choose to use them on another device do we ask for your mobile number and a one-time code sent by SMS; the saved list is then stored under that verified number so nobody else can open it.', 'gu', '<b_a>સેવ કરેલી રેસીપી અને તમારું સાપ્તાહિક આયોજન</b_a> તમારા ફોન પર રહે છે. ફક્ત જો તમે તેને બીજા ડિવાઇસ પર વાપરવાનું પસંદ કરો, તો અમે તમારો મોબાઇલ નંબર અને SMS દ્વારા મોકલેલ એક વારનો કોડ માંગીએ છીએ; સેવ કરેલી યાદી પછી તે ચકાસાયેલા નંબર હેઠળ રાખવામાં આવે છે જેથી બીજું કોઈ તેને ખોલી ન શકે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan features recipes from public recipe sites, with the creator''s name, photo credit and a link back, and steps written in our own words. To ask permission we email the creator at the contact address published on their own site, once. We keep that address, our email, their reply, and a phone number if they choose to send one, only to record their permission and to reach them about sharing. We stop and remove their recipes and photos if they tell us to. Our reader for public pages is described at <a_a>KidPoshanBot</a_a>.', 'hi', 'KidPoshan सार्वजनिक रेसिपी साइटों की रेसिपी दिखाता है, रचनाकार के नाम, फ़ोटो के श्रेय और मूल की ओर लिंक के साथ, और हमारे अपने शब्दों में लिखे चरणों के साथ। अनुमति माँगने के लिए हम रचनाकार को उनकी अपनी साइट पर प्रकाशित संपर्क पते पर एक बार ईमेल करते हैं। हम वह पता, हमारा ईमेल, उनका जवाब, और अगर वे भेजें तो एक फ़ोन नंबर, सिर्फ़ उनकी अनुमति दर्ज करने और साझा करने के बारे में उनसे संपर्क करने के लिए रखते हैं। अगर वे कहें तो हम उनकी रेसिपी और फ़ोटो रोक देते और हटा देते हैं। सार्वजनिक पेजों के लिए हमारे रीडर का वर्णन <a_a>KidPoshanBot</a_a> पर है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan features recipes from public recipe sites, with the creator''s name, photo credit and a link back, and steps written in our own words. To ask permission we email the creator at the contact address published on their own site, once. We keep that address, our email, their reply, and a phone number if they choose to send one, only to record their permission and to reach them about sharing. We stop and remove their recipes and photos if they tell us to. Our reader for public pages is described at <a_a>KidPoshanBot</a_a>.', 'bn', 'KidPoshan সার্বজনিক রেসিপি সাইটের রেসিপি দেখায়, নির্মাতার নাম, ছবির কৃতিত্ব ও মূলের লিঙ্কসহ, আর আমাদের নিজের ভাষায় লেখা ধাপসহ। অনুমতি চাইতে আমরা নির্মাতাকে তাঁদের নিজস্ব সাইটে প্রকাশিত যোগাযোগের ঠিকানায় একবার ইমেইল করি। আমরা সেই ঠিকানা, আমাদের ইমেইল, তাঁদের উত্তর, আর তাঁরা পাঠালে একটি ফোন নম্বর রাখি, শুধু তাঁদের অনুমতি নথিভুক্ত করতে ও ভাগ করে নেওয়া নিয়ে যোগাযোগ করতে। তাঁরা বললে আমরা তাঁদের রেসিপি ও ছবি বন্ধ করে সরিয়ে ফেলি। সার্বজনিক পেজের জন্য আমাদের রিডারের বর্ণনা <a_a>KidPoshanBot</a_a>-এ আছে।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('KidPoshan features recipes from public recipe sites, with the creator''s name, photo credit and a link back, and steps written in our own words. To ask permission we email the creator at the contact address published on their own site, once. We keep that address, our email, their reply, and a phone number if they choose to send one, only to record their permission and to reach them about sharing. We stop and remove their recipes and photos if they tell us to. Our reader for public pages is described at <a_a>KidPoshanBot</a_a>.', 'gu', 'KidPoshan સાર્વજનિક રેસીપી સાઇટોની રેસીપી બતાવે છે, રચયિતાના નામ, ફોટાના શ્રેય અને મૂળ તરફની લિંક સાથે, અને અમારા પોતાના શબ્દોમાં લખેલા પગલાં સાથે. પરવાનગી માંગવા અમે રચયિતાને તેમની પોતાની સાઇટ પર પ્રકાશિત સંપર્ક સરનામા પર એક વાર ઈમેલ કરીએ છીએ. અમે તે સરનામું, અમારો ઈમેલ, તેમનો જવાબ, અને જો તેઓ મોકલે તો એક ફોન નંબર, ફક્ત તેમની પરવાનગી નોંધવા અને વહેંચણી વિશે તેમનો સંપર્ક કરવા રાખીએ છીએ. જો તેઓ કહે તો અમે તેમની રેસીપી અને ફોટા બંધ કરીને દૂર કરીએ છીએ. સાર્વજનિક પેજ માટે અમારા રીડરનું વર્ણન <a_a>KidPoshanBot</a_a> પર છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('To send those permission requests and read the replies, KidPoshan connects to the Google account <b_a>kidposhan@gmail.com</b_a> through the Gmail API, with permission only to <b_b>send email</b_b> and to <b_c>read the replies to the emails we sent</b_c>. We do not read any other mail, we do not share Gmail data with anyone, we do not use it for advertising, and it is not used to train any AI model. A reply is read by our systems to record whether the creator agreed and any phone number given, and by the owner of the site. KidPoshan''s use of information received from Google APIs adheres to the <a_d>Google API Services User Data Policy</a_d>, including its Limited Use requirements.', 'hi', 'ये अनुमति अनुरोध भेजने और जवाब पढ़ने के लिए, KidPoshan Gmail API के ज़रिए Google खाते <b_a>kidposhan@gmail.com</b_a> से जुड़ता है, सिर्फ़ <b_b>ईमेल भेजने</b_b> और <b_c>हमारे भेजे ईमेल के जवाब पढ़ने</b_c> की अनुमति के साथ। हम कोई और मेल नहीं पढ़ते, Gmail डेटा किसी के साथ साझा नहीं करते, इसे विज्ञापन के लिए इस्तेमाल नहीं करते, और इसका इस्तेमाल किसी AI मॉडल को प्रशिक्षित करने में नहीं होता। जवाब हमारे सिस्टम यह दर्ज करने के लिए पढ़ते हैं कि रचनाकार सहमत हुए या नहीं और कोई फ़ोन नंबर दिया गया, और साइट के मालिक पढ़ते हैं। Google APIs से मिली जानकारी का KidPoshan का उपयोग <a_d>Google API Services User Data Policy</a_d> का पालन करता है, उसकी Limited Use आवश्यकताओं सहित।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('To send those permission requests and read the replies, KidPoshan connects to the Google account <b_a>kidposhan@gmail.com</b_a> through the Gmail API, with permission only to <b_b>send email</b_b> and to <b_c>read the replies to the emails we sent</b_c>. We do not read any other mail, we do not share Gmail data with anyone, we do not use it for advertising, and it is not used to train any AI model. A reply is read by our systems to record whether the creator agreed and any phone number given, and by the owner of the site. KidPoshan''s use of information received from Google APIs adheres to the <a_d>Google API Services User Data Policy</a_d>, including its Limited Use requirements.', 'bn', 'এই অনুমতির অনুরোধ পাঠাতে ও উত্তর পড়তে KidPoshan Gmail API-র মাধ্যমে Google অ্যাকাউন্ট <b_a>kidposhan@gmail.com</b_a>-এর সঙ্গে যুক্ত হয়, শুধু <b_b>ইমেইল পাঠানো</b_b> এবং <b_c>আমাদের পাঠানো ইমেইলের উত্তর পড়ার</b_c> অনুমতিসহ। আমরা অন্য কোনো মেইল পড়ি না, Gmail ডেটা কারও সঙ্গে শেয়ার করি না, বিজ্ঞাপনের জন্য ব্যবহার করি না, আর কোনো AI মডেল প্রশিক্ষণে এটি ব্যবহার হয় না। নির্মাতা রাজি হয়েছেন কি না ও কোনো ফোন নম্বর দেওয়া হয়েছে কি না তা নথিভুক্ত করতে উত্তর আমাদের সিস্টেম পড়ে, আর সাইটের মালিক পড়েন। Google API থেকে পাওয়া তথ্যের KidPoshan-এর ব্যবহার <a_d>Google API Services User Data Policy</a_d> মেনে চলে, তার Limited Use শর্তসহ।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('To send those permission requests and read the replies, KidPoshan connects to the Google account <b_a>kidposhan@gmail.com</b_a> through the Gmail API, with permission only to <b_b>send email</b_b> and to <b_c>read the replies to the emails we sent</b_c>. We do not read any other mail, we do not share Gmail data with anyone, we do not use it for advertising, and it is not used to train any AI model. A reply is read by our systems to record whether the creator agreed and any phone number given, and by the owner of the site. KidPoshan''s use of information received from Google APIs adheres to the <a_d>Google API Services User Data Policy</a_d>, including its Limited Use requirements.', 'gu', 'આ પરવાનગી વિનંતીઓ મોકલવા અને જવાબો વાંચવા, KidPoshan Gmail API દ્વારા Google ખાતા <b_a>kidposhan@gmail.com</b_a> સાથે જોડાય છે, ફક્ત <b_b>ઈમેલ મોકલવા</b_b> અને <b_c>અમે મોકલેલા ઈમેલના જવાબો વાંચવા</b_c> ની પરવાનગી સાથે. અમે બીજી કોઈ મેલ વાંચતા નથી, Gmail ડેટા કોઈ સાથે વહેંચતા નથી, તેને જાહેરાત માટે વાપરતા નથી, અને તેનો ઉપયોગ કોઈ AI મૉડલને તાલીમ આપવા થતો નથી. રચયિતા સંમત થયા કે નહીં અને કોઈ ફોન નંબર અપાયો કે નહીં તે નોંધવા જવાબ અમારી સિસ્ટમ વાંચે છે, અને સાઇટના માલિક વાંચે છે. Google APIs પાસેથી મળેલી માહિતીનો KidPoshan નો ઉપયોગ <a_d>Google API Services User Data Policy</a_d> નું પાલન કરે છે, તેની Limited Use જરૂરિયાતો સહિત.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The site runs on Cloudflare (hosting and database). We use Cloudflare''s AI service to rewrite recipe steps and Tavily to search the web for recipe pages; neither receives your name, number or email. Gmail (Google) is used only as described above. We do not sell or rent your information.', 'hi', 'साइट Cloudflare पर चलती है (होस्टिंग और डेटाबेस)। हम रेसिपी के चरण फिर से लिखने के लिए Cloudflare की AI सेवा और रेसिपी पेज खोजने के लिए Tavily का इस्तेमाल करते हैं; इनमें से किसी को आपका नाम, नंबर या ईमेल नहीं मिलता। Gmail (Google) का इस्तेमाल सिर्फ़ ऊपर बताए अनुसार होता है। हम आपकी जानकारी न बेचते हैं, न किराए पर देते हैं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The site runs on Cloudflare (hosting and database). We use Cloudflare''s AI service to rewrite recipe steps and Tavily to search the web for recipe pages; neither receives your name, number or email. Gmail (Google) is used only as described above. We do not sell or rent your information.', 'bn', 'সাইটটি Cloudflare-এ চলে (হোস্টিং ও ডেটাবেস)। আমরা রেসিপির ধাপ নতুন করে লিখতে Cloudflare-এর AI সেবা ও রেসিপি পেজ খুঁজতে Tavily ব্যবহার করি; এদের কেউই আপনার নাম, নম্বর বা ইমেইল পায় না। Gmail (Google) শুধু ওপরে বলা মতো ব্যবহার হয়। আমরা আপনার তথ্য বিক্রি বা ভাড়া দিই না।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('The site runs on Cloudflare (hosting and database). We use Cloudflare''s AI service to rewrite recipe steps and Tavily to search the web for recipe pages; neither receives your name, number or email. Gmail (Google) is used only as described above. We do not sell or rent your information.', 'gu', 'સાઇટ Cloudflare પર ચાલે છે (હોસ્ટિંગ અને ડેટાબેઝ). અમે રેસીપીના પગલાં ફરી લખવા Cloudflare ની AI સેવા અને રેસીપી પેજ શોધવા Tavily વાપરીએ છીએ; તેમાંથી કોઈને તમારું નામ, નંબર કે ઈમેલ મળતું નથી. Gmail (Google) ફક્ત ઉપર જણાવ્યા મુજબ વપરાય છે. અમે તમારી માહિતી વેચતા કે ભાડે આપતા નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We keep what you give us for as long as the site runs, or until you ask us to delete it. You can ask us to show you, correct or delete your name, number, email, ratings or remarks, or a creator''s details, by writing to <a_a>kidposhan@gmail.com</a_a>. We will deal with it promptly.', 'hi', 'आपने जो हमें दिया है उसे हम तब तक रखते हैं जब तक साइट चलती है, या जब तक आप उसे मिटाने को न कहें। आप <a_a>kidposhan@gmail.com</a_a> पर लिखकर अपना नाम, नंबर, ईमेल, रेटिंग या टिप्पणियाँ, या किसी रचनाकार का विवरण, दिखाने, सुधारने या मिटाने के लिए कह सकते हैं। हम इसे जल्द निपटाएँगे।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We keep what you give us for as long as the site runs, or until you ask us to delete it. You can ask us to show you, correct or delete your name, number, email, ratings or remarks, or a creator''s details, by writing to <a_a>kidposhan@gmail.com</a_a>. We will deal with it promptly.', 'bn', 'আপনি আমাদের যা দিয়েছেন তা আমরা রাখি যতদিন সাইট চলে, বা যতদিন না আপনি মুছে ফেলতে বলেন। আপনি <a_a>kidposhan@gmail.com</a_a>-এ লিখে আপনার নাম, নম্বর, ইমেইল, রেটিং বা মন্তব্য, বা কোনো নির্মাতার তথ্য, দেখাতে, সংশোধন করতে বা মুছতে বলতে পারেন। আমরা দ্রুত তা নিষ্পত্তি করব।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('We keep what you give us for as long as the site runs, or until you ask us to delete it. You can ask us to show you, correct or delete your name, number, email, ratings or remarks, or a creator''s details, by writing to <a_a>kidposhan@gmail.com</a_a>. We will deal with it promptly.', 'gu', 'તમે અમને જે આપ્યું છે તે અમે જ્યાં સુધી સાઇટ ચાલે છે, અથવા જ્યાં સુધી તમે તેને ભૂંસવા ન કહો ત્યાં સુધી રાખીએ છીએ. તમે <a_a>kidposhan@gmail.com</a_a> પર લખીને તમારું નામ, નંબર, ઈમેલ, રેટિંગ કે ટિપ્પણીઓ, અથવા કોઈ રચયિતાની વિગતો, બતાવવા, સુધારવા કે ભૂંસવા કહી શકો છો. અમે તેનો તુરંત નિકાલ કરીશું.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Packaged foods for kids scored out of {#} for your child''s age: cereals, noodles, biscuits, ready mixes and more. See the sugar, salt and fibre behind each score.', 'hi', 'बच्चों के पैकेज्ड खाने, आपके बच्चे की उम्र के लिए {#} में से स्कोर के साथ: सीरियल, नूडल्स, बिस्कुट, रेडी मिक्स और भी बहुत कुछ। हर स्कोर के पीछे की चीनी, नमक और फाइबर देखें।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Packaged foods for kids scored out of {#} for your child''s age: cereals, noodles, biscuits, ready mixes and more. See the sugar, salt and fibre behind each score.', 'bn', 'বাচ্চাদের প্যাকেটজাত খাবার, আপনার সন্তানের বয়সের জন্য {#}-এর মধ্যে স্কোরসহ: সিরিয়াল, নুডলস, বিস্কুট, রেডি মিক্স আরও অনেক কিছু। প্রতিটি স্কোরের পেছনের চিনি, নুন ও ফাইবার দেখুন।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Packaged foods for kids scored out of {#} for your child''s age: cereals, noodles, biscuits, ready mixes and more. See the sugar, salt and fibre behind each score.', 'gu', 'બાળકોના પેકેજ્ડ ખોરાક, તમારા બાળકની ઉંમર માટે {#} માંથી સ્કોર સાથે: સીરિયલ, નૂડલ્સ, બિસ્કિટ, રેડી મિક્સ અને ઘણું બધું. દરેક સ્કોર પાછળની ખાંડ, મીઠું અને ફાઇબર જુઓ.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product below gets a Poshan Score out of {#}, from the nutrition label printed on the pack, worked out for one realistic serving (the same way recipes are scored, so the two can be compared). The score is made of ten yes-or-no checks, each worth {#} points, and it is worked out for the age you pick. A low score is not a warning. It is a reason to keep it occasional. We search for new products every few hours and read their labels, and a product appears here once its label has been read and checked.', 'hi', 'नीचे हर प्रोडक्ट को पैक पर छपे पोषण लेबल से {#} में से एक Poshan Score मिलता है, एक यथार्थवादी सर्विंग के हिसाब से (उसी तरह जैसे रेसिपी स्कोर होती हैं, ताकि दोनों की तुलना हो सके)। स्कोर दस हाँ-या-नहीं जाँच से बनता है, हर एक के {#} अंक, और यह आपकी चुनी उम्र के लिए निकाला जाता है। कम स्कोर कोई चेतावनी नहीं है। यह उसे कभी-कभार रखने का एक कारण है। हम हर कुछ घंटों में नए प्रोडक्ट खोजते हैं और उनके लेबल पढ़ते हैं, और कोई प्रोडक्ट यहाँ तभी आता है जब उसका लेबल पढ़ा और जाँचा जा चुका हो।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product below gets a Poshan Score out of {#}, from the nutrition label printed on the pack, worked out for one realistic serving (the same way recipes are scored, so the two can be compared). The score is made of ten yes-or-no checks, each worth {#} points, and it is worked out for the age you pick. A low score is not a warning. It is a reason to keep it occasional. We search for new products every few hours and read their labels, and a product appears here once its label has been read and checked.', 'bn', 'নিচের প্রতিটি প্রোডাক্ট প্যাকে ছাপা পুষ্টি লেবেল থেকে {#}-এর মধ্যে একটি Poshan Score পায়, একটি বাস্তবসম্মত সার্ভিং হিসাবে (রেসিপির মতোই, যাতে দুটির তুলনা করা যায়)। স্কোর দশটি হ্যাঁ-না পরীক্ষা দিয়ে তৈরি, প্রতিটির {#} নম্বর, আর আপনার বেছে নেওয়া বয়সের জন্য হিসাব করা হয়। কম স্কোর কোনো সতর্কতা নয়। এটি সেটিকে মাঝেমধ্যে রাখার একটি কারণ। আমরা কয়েক ঘণ্টা পরপর নতুন প্রোডাক্ট খুঁজি ও তাদের লেবেল পড়ি, আর কোনো প্রোডাক্ট এখানে আসে তার লেবেল পড়া ও যাচাই হওয়ার পরই।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Every product below gets a Poshan Score out of {#}, from the nutrition label printed on the pack, worked out for one realistic serving (the same way recipes are scored, so the two can be compared). The score is made of ten yes-or-no checks, each worth {#} points, and it is worked out for the age you pick. A low score is not a warning. It is a reason to keep it occasional. We search for new products every few hours and read their labels, and a product appears here once its label has been read and checked.', 'gu', 'નીચેના દરેક પ્રોડક્ટને પેક પર છાપેલા પોષણ લેબલ પરથી {#} માંથી એક Poshan Score મળે છે, એક વાસ્તવિક સર્વિંગ મુજબ (રેસીપીની જેમ જ, જેથી બંનેની સરખામણી થઈ શકે). સ્કોર દસ હા-કે-ના તપાસથી બને છે, દરેકના {#} ગુણ, અને તે તમે પસંદ કરેલી ઉંમર માટે કઢાય છે. ઓછો સ્કોર ચેતવણી નથી. તે તેને ક્યારેક-ક્યારેક રાખવાનું એક કારણ છે. અમે દર થોડા કલાકે નવા પ્રોડક્ટ શોધીએ છીએ અને તેમના લેબલ વાંચીએ છીએ, અને કોઈ પ્રોડક્ટ અહીં ત્યારે જ આવે છે જ્યારે તેનું લેબલ વંચાઈ અને તપાસાઈ ગયું હોય.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Pack photos are the sellers'' or, where marked, from <a_d>Open Food Facts</a_d> contributors (CC BY-SA). Some label data comes from Open Food Facts under the Open Database Licence. The age guide is general and cautious. It is not medical advice.', 'hi', '<b_a>ICMR-NIN {#}</b_a> और <b_b>FSSAI</b_b> के मानक पर · Poshan Score एक स्वतंत्र रेटिंग है, कोई प्रमाणन नहीं<br_c/> पैक की फ़ोटो विक्रेताओं की हैं या, जहाँ चिह्नित है, <a_d>Open Food Facts</a_d> के योगदानकर्ताओं की (CC BY-SA)। कुछ लेबल डेटा Open Food Facts से Open Database Licence के तहत आता है। उम्र की जानकारी सामान्य और सावधानी वाली है। यह चिकित्सकीय सलाह नहीं है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Pack photos are the sellers'' or, where marked, from <a_d>Open Food Facts</a_d> contributors (CC BY-SA). Some label data comes from Open Food Facts under the Open Database Licence. The age guide is general and cautious. It is not medical advice.', 'bn', '<b_a>ICMR-NIN {#}</b_a> ও <b_b>FSSAI</b_b> মানদণ্ডে · Poshan Score একটি স্বাধীন রেটিং, কোনো সার্টিফিকেশন নয়<br_c/> প্যাকের ছবি বিক্রেতাদের বা, যেখানে চিহ্নিত, <a_d>Open Food Facts</a_d>-এর অবদানকারীদের (CC BY-SA)। কিছু লেবেল ডেটা Open Food Facts থেকে Open Database Licence-এর অধীনে আসে। বয়স অনুযায়ী নির্দেশিকা সাধারণ ও সতর্ক। এটি চিকিৎসা পরামর্শ নয়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Pack photos are the sellers'' or, where marked, from <a_d>Open Food Facts</a_d> contributors (CC BY-SA). Some label data comes from Open Food Facts under the Open Database Licence. The age guide is general and cautious. It is not medical advice.', 'gu', '<b_a>ICMR-NIN {#}</b_a> અને <b_b>FSSAI</b_b> ના ધોરણ પર · Poshan Score એક સ્વતંત્ર રેટિંગ છે, પ્રમાણપત્ર નથી<br_c/> પેકના ફોટા વેચનારાઓના છે અથવા, જ્યાં ચિહ્નિત હોય, <a_d>Open Food Facts</a_d> ના યોગદાનકર્તાઓના (CC BY-SA). કેટલાક લેબલ ડેટા Open Food Facts પરથી Open Database Licence હેઠળ આવે છે. ઉંમર મુજબની માહિતી સામાન્ય અને સાવચેતીભરી છે. તે તબીબી સલાહ નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('{#} kids'' recipes from cooks and cookbooks, each with a Poshan Score for every age from toddlers to adults. Breakfast, lunchbox, lunch, snacks and dinner, vegetarian, Jain and non-vegetarian.', 'hi', '{#} बच्चों की रेसिपी रसोइयों और कुकबुक से, हर एक के पास छोटे बच्चों से वयस्कों तक हर उम्र के लिए Poshan Score है। नाश्ता, लंचबॉक्स, दोपहर का खाना, स्नैक्स और रात का खाना, शाकाहारी, जैन और मांसाहारी।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('{#} kids'' recipes from cooks and cookbooks, each with a Poshan Score for every age from toddlers to adults. Breakfast, lunchbox, lunch, snacks and dinner, vegetarian, Jain and non-vegetarian.', 'bn', '{#}টি বাচ্চাদের রেসিপি রাঁধুনি ও কুকবুক থেকে, প্রতিটির ছোট শিশু থেকে প্রাপ্তবয়স্ক পর্যন্ত প্রতিটি বয়সের জন্য Poshan Score আছে। জলখাবার, টিফিনবক্স, দুপুরের খাবার, স্ন্যাকস ও রাতের খাবার, নিরামিষ, জৈন ও আমিষ।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('{#} kids'' recipes from cooks and cookbooks, each with a Poshan Score for every age from toddlers to adults. Breakfast, lunchbox, lunch, snacks and dinner, vegetarian, Jain and non-vegetarian.', 'gu', '{#} બાળકોની રેસીપી રસોઇયાઓ અને કુકબુકમાંથી, દરેકનો નાનાં બાળકોથી પુખ્ત સુધી દરેક ઉંમર માટે Poshan Score છે. નાસ્તો, લંચબોક્સ, બપોરનું ભોજન, નાસ્તા અને રાતનું ભોજન, શાકાહારી, જૈન અને માંસાહારી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score <small_b>by KidPoshan</small_b>', 'hi', 'Poshan Score <small_b>by KidPoshan</small_b>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score <small_b>by KidPoshan</small_b>', 'bn', 'Poshan Score <small_b>by KidPoshan</small_b>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score <small_b>by KidPoshan</small_b>', 'gu', 'Poshan Score <small_b>by KidPoshan</small_b>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('{#} recipes from various cooks and cookbooks, each credited to the person who wrote it. Every recipe has a Poshan Score out of {#}, worked out for one serving and for every age group from toddlers to adults. Open one to see the ingredients and the score for your child''s age, save it, and plan your week.', 'hi', '{#} रेसिपी अलग-अलग रसोइयों और कुकबुक से, हर एक उसे लिखने वाले के नाम के साथ। हर रेसिपी का {#} में से एक Poshan Score है, एक सर्विंग और छोटे बच्चों से वयस्कों तक हर उम्र समूह के लिए निकाला गया। किसी को खोलकर सामग्री और अपने बच्चे की उम्र का स्कोर देखें, उसे सेव करें, और अपने हफ़्ते की योजना बनाएँ।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('{#} recipes from various cooks and cookbooks, each credited to the person who wrote it. Every recipe has a Poshan Score out of {#}, worked out for one serving and for every age group from toddlers to adults. Open one to see the ingredients and the score for your child''s age, save it, and plan your week.', 'bn', '{#}টি রেসিপি বিভিন্ন রাঁধুনি ও কুকবুক থেকে, প্রতিটি যিনি লিখেছেন তাঁর নামসহ। প্রতিটি রেসিপির {#}-এর মধ্যে একটি Poshan Score আছে, এক সার্ভিং ও ছোট শিশু থেকে প্রাপ্তবয়স্ক পর্যন্ত প্রতিটি বয়সের গ্রুপের জন্য হিসাব করা। কোনোটি খুলে উপকরণ ও আপনার সন্তানের বয়সের স্কোর দেখুন, সেভ করুন, আর আপনার সপ্তাহের পরিকল্পনা করুন।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('{#} recipes from various cooks and cookbooks, each credited to the person who wrote it. Every recipe has a Poshan Score out of {#}, worked out for one serving and for every age group from toddlers to adults. Open one to see the ingredients and the score for your child''s age, save it, and plan your week.', 'gu', '{#} રેસીપી જુદા જુદા રસોઇયાઓ અને કુકબુકમાંથી, દરેક તે લખનારના નામ સાથે. દરેક રેસીપીનો {#} માંથી એક Poshan Score છે, એક સર્વિંગ અને નાનાં બાળકોથી પુખ્ત સુધી દરેક ઉંમર જૂથ માટે કાઢેલો. કોઈ ખોલીને સામગ્રી અને તમારા બાળકની ઉંમરનો સ્કોર જુઓ, તેને સેવ કરો, અને તમારા અઠવાડિયાનું આયોજન કરો.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is an independent rating, not a certification, and the age guide is general, not medical advice.', 'hi', 'Poshan Score एक स्वतंत्र रेटिंग है, कोई प्रमाणन नहीं, और उम्र की जानकारी सामान्य है, चिकित्सकीय सलाह नहीं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is an independent rating, not a certification, and the age guide is general, not medical advice.', 'bn', 'Poshan Score একটি স্বাধীন রেটিং, কোনো সার্টিফিকেশন নয়, আর বয়স অনুযায়ী নির্দেশিকা সাধারণ, চিকিৎসা পরামর্শ নয়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is an independent rating, not a certification, and the age guide is general, not medical advice.', 'gu', 'Poshan Score એક સ્વતંત્ર રેટિંગ છે, પ્રમાણપત્ર નથી, અને ઉંમર મુજબની માહિતી સામાન્ય છે, તબીબી સલાહ નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scan the barcode on any packaged food and see its Poshan Score for your child''s age. If we do not know the pack yet, photograph the front and back and we will score it.', 'hi', 'किसी भी पैकेज्ड खाने पर बारकोड स्कैन करें और अपने बच्चे की उम्र के लिए उसका Poshan Score देखें। अगर हम पैक को अभी नहीं जानते, तो आगे और पीछे की फ़ोटो लें और हम उसे स्कोर करेंगे।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scan the barcode on any packaged food and see its Poshan Score for your child''s age. If we do not know the pack yet, photograph the front and back and we will score it.', 'bn', 'যেকোনো প্যাকেটজাত খাবারের বারকোড স্ক্যান করুন আর আপনার সন্তানের বয়সের জন্য তার Poshan Score দেখুন। প্যাকটি আমরা এখনও না চিনলে সামনে ও পেছনের ছবি তুলুন, আমরা স্কোর করব।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scan the barcode on any packaged food and see its Poshan Score for your child''s age. If we do not know the pack yet, photograph the front and back and we will score it.', 'gu', 'કોઈ પણ પેકેજ્ડ ખોરાક પરનો બારકોડ સ્કેન કરો અને તમારા બાળકની ઉંમર માટે તેનો Poshan Score જુઓ. જો અમે પેકને હજી ઓળખતા ન હોઈએ, તો આગળ અને પાછળના ફોટા લો અને અમે તેને સ્કોર કરીશું.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scan the barcode on any packaged food. If we know the pack you see its Poshan Score straight away. If we do not, photograph the front and the back of the pack and we score it for you, then add it for every parent once our team has checked it.', 'hi', 'किसी भी पैकेज्ड खाने पर बारकोड स्कैन करें। अगर हम पैक को जानते हैं तो आप उसका Poshan Score तुरंत देखते हैं। अगर नहीं जानते, तो पैक के आगे और पीछे की फ़ोटो लें और हम आपके लिए स्कोर करते हैं, फिर हमारी टीम के जाँचने के बाद उसे हर अभिभावक के लिए जोड़ देते हैं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scan the barcode on any packaged food. If we know the pack you see its Poshan Score straight away. If we do not, photograph the front and the back of the pack and we score it for you, then add it for every parent once our team has checked it.', 'bn', 'যেকোনো প্যাকেটজাত খাবারের বারকোড স্ক্যান করুন। প্যাকটি আমরা চিনলে আপনি সঙ্গে সঙ্গে তার Poshan Score দেখেন। না চিনলে প্যাকের সামনে ও পেছনের ছবি তুলুন, আমরা আপনার জন্য স্কোর করি, তারপর আমাদের দল যাচাই করার পর প্রতিটি অভিভাবকের জন্য যোগ করি।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Scan the barcode on any packaged food. If we know the pack you see its Poshan Score straight away. If we do not, photograph the front and the back of the pack and we score it for you, then add it for every parent once our team has checked it.', 'gu', 'કોઈ પણ પેકેજ્ડ ખોરાક પરનો બારકોડ સ્કેન કરો. જો અમે પેકને ઓળખીએ તો તમે તેનો Poshan Score તરત જુઓ છો. જો ન ઓળખીએ, તો પેકના આગળ અને પાછળના ફોટા લો અને અમે તમારા માટે સ્કોર કરીએ છીએ, પછી અમારી ટીમ તપાસે ત્યારે દરેક વાલી માટે ઉમેરીએ છીએ.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Take a photo of the barcode instead<input_a/>', 'hi', 'इसके बजाय बारकोड की फ़ोटो लें<input_a/>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Take a photo of the barcode instead<input_a/>', 'bn', 'তার বদলে বারকোডের ছবি তুলুন<input_a/>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Take a photo of the barcode instead<input_a/>', 'gu', 'તેના બદલે બારકોડનો ફોટો લો<input_a/>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Photos you send are kept to score the pack. They may be shown with the pack on the Products page after our team has checked it, so please photograph only the pack, not people. We keep no name, number or address with a scan. See the <a_a>privacy page</a_a>.', 'hi', 'आपकी भेजी फ़ोटो पैक को स्कोर करने के लिए रखी जाती हैं। हमारी टीम के जाँचने के बाद वे पैक के साथ प्रोडक्ट पेज पर दिखाई जा सकती हैं, इसलिए कृपया सिर्फ़ पैक की फ़ोटो लें, लोगों की नहीं। हम किसी स्कैन के साथ कोई नाम, नंबर या पता नहीं रखते। <a_a>गोपनीयता पेज</a_a> देखें।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Photos you send are kept to score the pack. They may be shown with the pack on the Products page after our team has checked it, so please photograph only the pack, not people. We keep no name, number or address with a scan. See the <a_a>privacy page</a_a>.', 'bn', 'আপনার পাঠানো ছবি প্যাক স্কোর করতে রাখা হয়। আমাদের দল যাচাই করার পর সেগুলো প্যাকের সঙ্গে প্রোডাক্ট পেজে দেখানো হতে পারে, তাই অনুগ্রহ করে শুধু প্যাকের ছবি তুলুন, মানুষের নয়। আমরা কোনো স্ক্যানের সঙ্গে কোনো নাম, নম্বর বা ঠিকানা রাখি না। <a_a>গোপনীয়তা পেজ</a_a> দেখুন।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Photos you send are kept to score the pack. They may be shown with the pack on the Products page after our team has checked it, so please photograph only the pack, not people. We keep no name, number or address with a scan. See the <a_a>privacy page</a_a>.', 'gu', 'તમે મોકલેલા ફોટા પેકને સ્કોર કરવા રાખવામાં આવે છે. અમારી ટીમ તપાસે પછી તે પેક સાથે પ્રોડક્ટ પેજ પર બતાવાઈ શકે છે, તેથી કૃપા કરીને ફક્ત પેકનો ફોટો લો, લોકોનો નહીં. અમે કોઈ સ્કેન સાથે કોઈ નામ, નંબર કે સરનામું રાખતા નથી. <a_a>ગોપનીયતા પેજ</a_a> જુઓ.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Label data may come from <a_d>Open Food Facts</a_d> contributors (Open Database Licence) or from photos sent by parents and read by our label reader, and is checked before a pack is listed. The age guide is general and cautious. It is not medical advice.', 'hi', '<b_a>ICMR-NIN {#}</b_a> और <b_b>FSSAI</b_b> के मानक पर · Poshan Score एक स्वतंत्र रेटिंग है, कोई प्रमाणन नहीं<br_c/> लेबल डेटा <a_d>Open Food Facts</a_d> के योगदानकर्ताओं (Open Database Licence) या अभिभावकों की भेजी और हमारे लेबल रीडर से पढ़ी गई फ़ोटो से आ सकता है, और पैक सूचीबद्ध होने से पहले जाँचा जाता है। उम्र की जानकारी सामान्य और सावधानी वाली है। यह चिकित्सकीय सलाह नहीं है।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Label data may come from <a_d>Open Food Facts</a_d> contributors (Open Database Licence) or from photos sent by parents and read by our label reader, and is checked before a pack is listed. The age guide is general and cautious. It is not medical advice.', 'bn', '<b_a>ICMR-NIN {#}</b_a> ও <b_b>FSSAI</b_b> মানদণ্ডে · Poshan Score একটি স্বাধীন রেটিং, কোনো সার্টিফিকেশন নয়<br_c/> লেবেল ডেটা আসতে পারে <a_d>Open Food Facts</a_d>-এর অবদানকারীদের (Open Database Licence) থেকে বা অভিভাবকদের পাঠানো ও আমাদের লেবেল রিডারের পড়া ছবি থেকে, আর প্যাক তালিকাভুক্ত হওয়ার আগে যাচাই করা হয়। বয়স অনুযায়ী নির্দেশিকা সাধারণ ও সতর্ক। এটি চিকিৎসা পরামর্শ নয়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Label data may come from <a_d>Open Food Facts</a_d> contributors (Open Database Licence) or from photos sent by parents and read by our label reader, and is checked before a pack is listed. The age guide is general and cautious. It is not medical advice.', 'gu', '<b_a>ICMR-NIN {#}</b_a> અને <b_b>FSSAI</b_b> ના ધોરણ પર · Poshan Score એક સ્વતંત્ર રેટિંગ છે, પ્રમાણપત્ર નથી<br_c/> લેબલ ડેટા <a_d>Open Food Facts</a_d> ના યોગદાનકર્તાઓ (Open Database Licence) પાસેથી અથવા વાલીઓએ મોકલેલા અને અમારા લેબલ રીડરે વાંચેલા ફોટા પરથી આવી શકે છે, અને પેક યાદીબદ્ધ થાય તે પહેલાં તપાસાય છે. ઉંમર મુજબની માહિતી સામાન્ય અને સાવચેતીભરી છે. તે તબીબી સલાહ નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Recipe ideas for children by age, meal, season and food preference (veg, Jain, non-veg), each with a Poshan Score out of {#}. Save the ones you like and plan the week.', 'hi', 'बच्चों के लिए रेसिपी आइडिया, उम्र, भोजन, मौसम और खाने की पसंद (वेज, जैन, नॉन-वेज) के हिसाब से, हर एक का {#} में से Poshan Score। जो पसंद आएँ उन्हें सेव करें और हफ़्ते की योजना बनाएँ।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Recipe ideas for children by age, meal, season and food preference (veg, Jain, non-veg), each with a Poshan Score out of {#}. Save the ones you like and plan the week.', 'bn', 'বাচ্চাদের জন্য রেসিপি আইডিয়া, বয়স, বেলা, ঋতু ও খাবারের পছন্দ (নিরামিষ, জৈন, আমিষ) অনুযায়ী, প্রতিটির {#}-এর মধ্যে Poshan Score। যেগুলো ভালো লাগে সেভ করুন ও সপ্তাহের পরিকল্পনা করুন।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Recipe ideas for children by age, meal, season and food preference (veg, Jain, non-veg), each with a Poshan Score out of {#}. Save the ones you like and plan the week.', 'gu', 'બાળકો માટે રેસીપી આઈડિયા, ઉંમર, ભોજન, ઋતુ અને ખોરાકની પસંદગી (શાકાહારી, જૈન, માંસાહારી) મુજબ, દરેકનો {#} માંથી Poshan Score. જે ગમે તે સેવ કરો અને અઠવાડિયાનું આયોજન કરો.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Saved<span_b></span_b>', 'hi', 'सेव<span_b></span_b>', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
