INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Dish photos belong to their creators and link back to the original recipe. Pack photos are the sellers''.', 'hi', '<b_a>ICMR-NIN {#}</b_a> और <b_b>FSSAI</b_b> के मानक पर · Poshan Score एक स्वतंत्र रेटिंग है, कोई प्रमाणन नहीं<br_c/> डिश की फ़ोटो उनके रचनाकारों की हैं और मूल रेसिपी से जुड़ती हैं। पैक की फ़ोटो विक्रेताओं की हैं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Dish photos belong to their creators and link back to the original recipe. Pack photos are the sellers''.', 'bn', '<b_a>ICMR-NIN {#}</b_a> ও <b_b>FSSAI</b_b> মানদণ্ডে · Poshan Score একটি স্বাধীন রেটিং, কোনো সার্টিফিকেশন নয়<br_c/> খাবারের ছবি তাদের নির্মাতাদের এবং মূল রেসিপির সঙ্গে যুক্ত। প্যাকের ছবি বিক্রেতাদের।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Benchmarked against <b_a>ICMR-NIN {#}</b_a> and <b_b>FSSAI</b_b> · Poshan Score is an independent rating, not a certification<br_c/> Dish photos belong to their creators and link back to the original recipe. Pack photos are the sellers''.', 'gu', '<b_a>ICMR-NIN {#}</b_a> અને <b_b>FSSAI</b_b> ના ધોરણ પર · Poshan Score એક સ્વતંત્ર રેટિંગ છે, પ્રમાણપત્ર નથી<br_c/> વાનગીના ફોટા તેમના રચયિતાઓના છે અને મૂળ રેસીપી સાથે જોડાયેલા છે. પેકના ફોટા વેચનારાઓના છે.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Put any two packaged foods side by side: the Poshan Score, the ten yes-or-no checks and the score for every age from toddlers to adults.', 'hi', 'कोई भी दो पैकेज्ड खाने आमने-सामने रखें: Poshan Score, दस हाँ-या-नहीं जाँच और छोटे बच्चों से वयस्कों तक हर उम्र का स्कोर।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Put any two packaged foods side by side: the Poshan Score, the ten yes-or-no checks and the score for every age from toddlers to adults.', 'bn', 'যেকোনো দুটি প্যাকেটজাত খাবার পাশাপাশি রাখুন: Poshan Score, দশটি হ্যাঁ-না পরীক্ষা আর ছোট শিশু থেকে প্রাপ্তবয়স্ক পর্যন্ত প্রতিটি বয়সের স্কোর।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Put any two packaged foods side by side: the Poshan Score, the ten yes-or-no checks and the score for every age from toddlers to adults.', 'gu', 'કોઈ પણ બે પેકેજ્ડ ખોરાક સામસામે મૂકો: Poshan Score, દસ હા-કે-ના તપાસ અને નાનાં બાળકોથી પુખ્ત સુધી દરેક ઉંમરનો સ્કોર.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Choose two products to see them side by side: the score, each of the ten checks, and the score at every age.', 'hi', 'दो प्रोडक्ट चुनें और उन्हें आमने-सामने देखें: स्कोर, दसों जाँच में से हर एक, और हर उम्र का स्कोर।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Choose two products to see them side by side: the score, each of the ten checks, and the score at every age.', 'bn', 'দুটি প্রোডাক্ট বেছে নিন আর পাশাপাশি দেখুন: স্কোর, দশটি পরীক্ষার প্রতিটি, আর প্রতিটি বয়সের স্কোর।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Choose two products to see them side by side: the score, each of the ten checks, and the score at every age.', 'gu', 'બે પ્રોડક્ટ પસંદ કરો અને તેમને સામસામે જુઓ: સ્કોર, દસેય તપાસમાંથી દરેક, અને દરેક ઉંમરનો સ્કોર.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is an independent rating, not a certification, and no brand pays to be here. Label values come from the pack''s own page or Open Food Facts. The age guide is general, not medical advice.', 'hi', 'Poshan Score एक स्वतंत्र रेटिंग है, कोई प्रमाणन नहीं, और कोई ब्रांड यहाँ आने के लिए भुगतान नहीं करता। लेबल के मान पैक के अपने पेज या Open Food Facts से आते हैं। उम्र की जानकारी सामान्य है, चिकित्सकीय सलाह नहीं।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is an independent rating, not a certification, and no brand pays to be here. Label values come from the pack''s own page or Open Food Facts. The age guide is general, not medical advice.', 'bn', 'Poshan Score একটি স্বাধীন রেটিং, কোনো সার্টিফিকেশন নয়, আর কোনো ব্র্যান্ড এখানে থাকার জন্য টাকা দেয় না। লেবেলের মান প্যাকের নিজস্ব পেজ বা Open Food Facts থেকে আসে। বয়স অনুযায়ী নির্দেশিকা সাধারণ, চিকিৎসা পরামর্শ নয়।', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
INSERT INTO kp_ui_i18n (key, lang, tgt, status, model, updated_at) VALUES ('Poshan Score is an independent rating, not a certification, and no brand pays to be here. Label values come from the pack''s own page or Open Food Facts. The age guide is general, not medical advice.', 'gu', 'Poshan Score એક સ્વતંત્ર રેટિંગ છે, પ્રમાણપત્ર નથી, અને કોઈ બ્રાન્ડ અહીં આવવા ચૂકવણી કરતી નથી. લેબલની કિંમતો પેકના પોતાના પેજ અથવા Open Food Facts પરથી આવે છે. ઉંમર મુજબની માહિતી સામાન્ય છે, તબીબી સલાહ નથી.', 'claude', 'claude-in-session', datetime('now')) ON CONFLICT(key, lang) DO UPDATE SET tgt = excluded.tgt, status = 'claude', model = excluded.model, updated_at = excluded.updated_at WHERE kp_ui_i18n.status != 'reviewed';
